// The label popover (docs/06a-labels.qmd, D36): opens beside a checked box or a margin line. Lists the labels
// on the passage (click to remove), the viewer's other labels (click to add, most recent first), a search box
// and "New label…". Nothing else is typed on the page; creating a label goes to the frame.
import type { LabelInfo } from '../../../shared/types.ts'

export interface PopoverModel {
  title: string
  subtitle?: string
  inherited: Array<{ label: LabelInfo; markId: string; from: string }>   // from an enclosing mark (D38)
  excluded: Array<{ label: LabelInfo; markId: string; from: string }>    // excepted from an enclosing mark
  applied: LabelInfo[]
  choices: LabelInfo[]          // the viewer's labels (mine) and the ones published to them, most recent first
  canCreate: boolean
  canRemove: boolean
  canEditText?: boolean          // Teach mode, a block: offer the in-place editor (D40)
  hasEdit?: boolean              // the block already shows the viewer's edit
}
export interface PopoverHandlers {
  add(l: LabelInfo): void
  remove(l: LabelInfo): void
  except(markId: string, l: LabelInfo): void      // exclude this block from an enclosing mark's label
  include(markId: string, l: LabelInfo): void     // undo that
  create(name: string): void
  close(): void
  editText?(): void
}

export class LabelPopover {
  el: HTMLElement
  private model: PopoverModel | null = null
  private handlers: PopoverHandlers | null = null
  private q = ''
  private anchorRect: DOMRect | null = null
  constructor(private layer: HTMLElement) {
    this.el = document.createElement('div')
    this.el.className = 'yrS4-pop'
    this.el.setAttribute('role', 'dialog')
    this.el.hidden = true
    layer.appendChild(this.el)
    document.addEventListener('mousedown', (e) => {
      if (this.el.hidden) return
      if (e.composedPath().includes(this.el)) return
      // a click on a box re-opens for that box (boot handles it); anything else closes
      this.hide()
    })
    document.addEventListener('keydown', (e) => {
      if (!this.el.hidden && e.key === 'Escape') {
        e.stopPropagation()
        this.hide()
      }
    })
  }

  get visible() {
    return !this.el.hidden
  }

  show(rect: DOMRect, model: PopoverModel, handlers: PopoverHandlers) {
    this.model = model
    this.handlers = handlers
    this.anchorRect = rect
    this.q = ''
    this.render()
    this.el.hidden = false
    this.place()
    const input = this.el.querySelector<HTMLInputElement>('input')
    setTimeout(() => input?.focus({ preventScroll: true }), 0)
  }

  /** Re-render with new data while open (after a label was added or removed). */
  update(model: PopoverModel) {
    if (this.el.hidden) return
    this.model = model
    this.render()
    this.place()
  }

  hide() {
    if (this.el.hidden) return
    this.el.hidden = true
    this.handlers?.close()
    this.model = null
    this.handlers = null
  }

  private place() {
    const r = this.anchorRect
    if (!r) return
    const w = this.el.offsetWidth || 280
    const h = this.el.offsetHeight || 200
    const vw = document.documentElement.clientWidth
    let left = r.right + window.scrollX + 8
    if (left + w > window.scrollX + vw - 8) left = Math.max(8, r.left + window.scrollX - w - 8)
    let top = r.top + window.scrollY - 6
    const maxTop = window.scrollY + window.innerHeight - h - 8
    if (top > maxTop) top = Math.max(window.scrollY + 8, maxTop)
    this.el.style.left = `${left}px`
    this.el.style.top = `${top}px`
  }

  private render() {
    const m = this.model!
    const h = this.handlers!
    this.el.replaceChildren()
    const head = document.createElement('div')
    head.className = 'yrS4-pop-head'
    head.innerHTML = `<strong></strong><span class="yrS4-pop-sub"></span><button type="button" class="yrS4-pop-x" aria-label="Close">×</button>`
    head.querySelector('strong')!.textContent = m.title
    head.querySelector('.yrS4-pop-sub')!.textContent = m.subtitle || ''
    head.querySelector('button')!.addEventListener('click', () => this.hide())
    this.el.appendChild(head)

    if (m.applied.length) {
      const row = document.createElement('div')
      row.className = 'yrS4-pop-row'
      row.append(this.label('On it:'))
      for (const l of m.applied) row.appendChild(this.chip(l, true, () => (m.canRemove ? h.remove(l) : undefined), m.canRemove ? `Remove "${l.name}"` : l.name))
      this.el.appendChild(row)
    }
    for (const x of m.inherited) {
      const row = document.createElement('div')
      row.className = 'yrS4-pop-row'
      row.append(this.label(`From ${x.from}:`))
      row.appendChild(this.chip(x.label, true, () => (m.canRemove ? h.except(x.markId, x.label) : undefined), m.canRemove ? `Except this part from "${x.label.name}"` : `${x.label.name}, from ${x.from}`))
      this.el.appendChild(row)
    }
    for (const x of m.excluded) {
      const row = document.createElement('div')
      row.className = 'yrS4-pop-row'
      row.append(this.label(`Excepted from ${x.from}:`))
      const c = this.chip(x.label, false, () => (m.canRemove ? h.include(x.markId, x.label) : undefined), m.canRemove ? `Include it in "${x.label.name}" again` : `${x.label.name}`)
      c.classList.add('excluded')
      row.appendChild(c)
      if (m.canRemove) {
        const b = document.createElement('button')
        b.type = 'button'
        b.className = 'yrS4-pop-new'
        b.textContent = 'include again'
        b.addEventListener('click', () => h.include(x.markId, x.label))
        row.appendChild(b)
      }
      this.el.appendChild(row)
    }

    const search = document.createElement('input')
    search.type = 'search'
    search.placeholder = m.choices.length ? 'Find or make a label…' : 'New label name…'
    search.value = this.q
    search.setAttribute('aria-label', 'Find or make a label')
    search.addEventListener('input', () => {
      this.q = search.value
      this.renderChoices()
    })
    search.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter') return
      e.preventDefault()
      const q = this.q.trim()
      const appliedIds = new Set(m.applied.map((l) => l.id))
      const list = this.filtered().filter((l) => !appliedIds.has(l.id))
      const exact = list.find((l) => l.name.toLowerCase() === q.toLowerCase())
      if (exact) h.add(exact)
      else if (list.length === 1 && q) h.add(list[0])
      else if (q && m.canCreate) h.create(q)
      else if (!q && list.length) h.add(list[0])
    })
    this.el.appendChild(search)
    const choices = document.createElement('div')
    choices.className = 'yrS4-pop-choices'
    this.el.appendChild(choices)
    this.renderChoices()
    if (m.canEditText && h.editText) {
      const row = document.createElement('div')
      row.className = 'yrS4-pop-row'
      const b = document.createElement('button')
      b.type = 'button'
      b.className = 'yrS4-pop-new'
      b.textContent = m.hasEdit ? '✎ Edit my edit of this text' : '✎ Edit this text (a proposal, shown to you only)'
      b.addEventListener('click', () => {
        this.hide()
        h.editText!()
      })
      row.appendChild(b)
      this.el.appendChild(row)
    }
    const hint = document.createElement('div')
    hint.className = 'yrS4-pop-hint'
    hint.textContent = 'Click a label to add it; Enter picks the first match or makes a new one; Esc closes.'
    this.el.appendChild(hint)
  }

  private filtered(): LabelInfo[] {
    const m = this.model!
    const q = this.q.trim().toLowerCase()
    return m.choices.filter((l) => !q || l.name.toLowerCase().includes(q))
  }

  private renderChoices() {
    const m = this.model!
    const h = this.handlers!
    const box = this.el.querySelector<HTMLElement>('.yrS4-pop-choices')
    if (!box) return
    box.replaceChildren()
    const appliedIds = new Set([...m.applied.map((l) => l.id), ...m.inherited.map((x) => x.label.id), ...m.excluded.map((x) => x.label.id)])
    const list = this.filtered().filter((l) => !appliedIds.has(l.id))
    const mine = list.filter((l) => l.mine)
    const theirs = list.filter((l) => !l.mine)
    const put = (items: LabelInfo[], title?: string) => {
      if (!items.length) return
      const row = document.createElement('div')
      row.className = 'yrS4-pop-row'
      if (title) row.append(this.label(title))
      for (const l of items) row.appendChild(this.chip(l, false, () => h.add(l), `Add "${l.name}"`))
      box.appendChild(row)
    }
    put(mine, m.applied.length || m.inherited.length ? 'Add:' : undefined)
    put(theirs, 'Published to you:')
    const q = this.q.trim()
    if (m.canCreate && q && !m.choices.some((l) => l.name.toLowerCase() === q.toLowerCase())) {
      const b = document.createElement('button')
      b.type = 'button'
      b.className = 'yrS4-pop-new'
      b.textContent = `+ New label “${q}”`
      b.addEventListener('click', () => h.create(q))
      box.appendChild(b)
    } else if (m.canCreate && !q) {
      const b = document.createElement('button')
      b.type = 'button'
      b.className = 'yrS4-pop-new muted'
      b.textContent = '+ New label… (type a name above)'
      b.addEventListener('click', () => this.el.querySelector<HTMLInputElement>('input')?.focus())
      box.appendChild(b)
    }
    if (!list.length && !q && !m.canCreate) box.append(this.label('No other labels.'))
  }

  private label(text: string): HTMLElement {
    const s = document.createElement('span')
    s.className = 'yrS4-pop-lbl'
    s.textContent = text
    return s
  }
  private chip(l: LabelInfo, on: boolean, onClick: () => void, title: string): HTMLElement {
    const b = document.createElement('button')
    b.type = 'button'
    b.className = `yrS4-chip${on ? ' on' : ''}`
    b.title = title
    b.style.setProperty('--c', l.color)
    b.innerHTML = `<span class="yrS4-chip-dot"></span><span class="yrS4-chip-name"></span>${on ? '<span class="yrS4-chip-x" aria-hidden="true">×</span>' : ''}`
    b.querySelector('.yrS4-chip-name')!.textContent = l.name
    b.addEventListener('click', (e) => {
      e.preventDefault()
      onClick()
    })
    return b
  }
}
