// yrS4 page script (docs/03-architecture.qmd). Loaded by one include line in a book's pages, or by the bookmarklet.
// It holds no key and makes no backend call: everything goes through the frame (an iframe on the platform origin).
import type { Anchor, ExceptPart, LabelInfo, MarkRow } from '../../shared/types.ts'
import type { FrameToPage, OverlayState } from '../../shared/protocol.ts'
import { PROTOCOL } from '../../shared/protocol.ts'
import { canonicalPageId, pagePathFor } from '../../shared/pageid.ts'
import { pickAdapter, type BookAdapter, type HeadingInfo } from './adapters/index.ts'
import { extractText, type PageText } from './anchor/text.ts'
import { describeBlock, describePage, describeRange, describeSection, type DescribeOptions } from './anchor/describe.ts'
import { findAnchor, findQuote } from './anchor/find.ts'
import { fuzzyFind } from './anchor/fuzzy.ts'
import { rangeFor } from './anchor/text.ts'
import { installHighlightStyles, Painter, paintClassFor, type PaintClass } from './render/highlights.ts'
import { colorsOf, MarginBars, type Placed } from './render/margin.ts'
import { BLOCK_SELECTOR, BlockBoxes, findBlocks, type BlockState, type BlockTarget, type Inherited } from './render/blocks.ts'
import { TocView } from './render/toc.ts'
import { Edits } from './edit/edits.ts'
import { htmlToMarkdown } from './edit/html2md.ts'
import { InlineEditor } from './edit/editor.ts'
import { Legend, legendItems } from './render/legend.ts'
import { ASK_ACTION, HeadingButtons, labelActions, NOTE_ONLY, STUDENT_ACTIONS, TEACH_ACTIONS, Toolbar, type ToolbarAction } from './toolbar/toolbar.ts'
import { LabelPopover, type PopoverModel } from './toolbar/popover.ts'
import { Bridge } from './bridge.ts'
import { buildUi, type OverlayUi } from './ui.ts'

declare const __YRS4_VERSION__: string
const VERSION = typeof __YRS4_VERSION__ === 'string' ? __YRS4_VERSION__ : 'dev'
const DEFAULT_PLATFORM = 'https://subjexts.github.io'
const GENERATED = ['.yr-collapse-buttons', '.yr-collapse-btn', '.yr-ways-btn', '.yr-ways-title', '.chapter-number', '.header-section-number', '.yr-update-bar']
const OFF_KEY = 'yrS4-off'          // "subjexts off for me" (this browser, this book's origin)
const FORCE_KEY = 'yrS4-force'      // the reader asked for the overlay although it is off for students (session)

interface Config {
  pkg: string
  platform: string
  generator?: string
  site?: string
  versionSuffix?: string
}

function readConfig(): Config | null {
  const el = (document.currentScript as HTMLScriptElement | null) || document.querySelector<HTMLScriptElement>('script[data-package]')
  const w = window as unknown as { yrS4Config?: Partial<Config> & { package?: string } }
  const pkg = el?.dataset.package || w.yrS4Config?.package || w.yrS4Config?.pkg
  if (!pkg) return null
  return {
    pkg,
    platform: (el?.dataset.platform || w.yrS4Config?.platform || DEFAULT_PLATFORM).replace(/\/$/, ''),
    generator: el?.dataset.generator || w.yrS4Config?.generator,
    site: el?.dataset.site || w.yrS4Config?.site,
    versionSuffix: el?.dataset.versionSuffix || w.yrS4Config?.versionSuffix,
  }
}

const norm = (s: string) => s.replace(/\s+/g, ' ').trim()
function store(key: string, value: string | null, session = false) {
  try {
    const st = session ? sessionStorage : localStorage
    if (value === null) st.removeItem(key)
    else st.setItem(key, value)
  } catch { /* storage may be blocked */ }
}
function read(key: string, session = false): string | null {
  try {
    return (session ? sessionStorage : localStorage).getItem(key)
  } catch {
    return null
  }
}

class Overlay {
  adapter!: BookAdapter
  root!: HTMLElement
  pt!: PageText
  headings: HeadingInfo[] = []
  ui!: OverlayUi
  bridge!: Bridge
  painter = new Painter()
  bars!: MarginBars
  boxes!: BlockBoxes
  legend!: Legend
  toc!: TocView
  edits = new Edits()
  editor = new InlineEditor()
  private renderWaiters = new Map<string, (html: string) => void>()
  private draftIds = new Map<string, string>()   // draftKey → mark id once the frame has stored a draft
  private menu!: HTMLElement
  popover!: LabelPopover
  toolbar!: Toolbar
  headBtns!: HeadingButtons
  state: OverlayState | null = null
  marks: MarkRow[] = []
  placed: Placed[] = []
  orphans: string[] = []
  reattached = new Map<string, Anchor>()
  pageCoverage: Record<string, 'full' | 'partial'> = {}
  activity: Array<{ anchor: Anchor; emoji: string; label: string; n: number }> = []
  private activityLayer: HTMLElement | null = null
  page: string
  path: string
  section: string | null
  offForMe: boolean
  force: boolean
  pendingAnchor: Anchor | null = null
  redrawTimer: number | undefined
  private popTarget: BlockTarget | null = null
  private hoverHeading: HTMLElement | null = null
  private hoverBlock: HTMLElement | null = null

  constructor(readonly cfg: Config) {
    this.path = pagePathFor(location.href, cfg.site)
    this.page = canonicalPageId(this.path, cfg.versionSuffix)
    const params = new URLSearchParams(location.search)
    // ?section=slug is remembered in the book origin's storage (it's public information).
    const q = params.get('section')
    if (q !== null) {
      if (q === '' || q === 'off') store('yrS4-section', null)
      else store('yrS4-section', q)
    }
    this.section = q && q !== 'off' ? q : read('yrS4-section')
    // ?subjexts=on: show the overlay although it is off for students (so staff can sign in); ?subjexts=off: off for me.
    const sx = params.get('subjexts')
    if (sx === 'on') {
      store(FORCE_KEY, '1', true)
      store(OFF_KEY, null)
    } else if (sx === 'off') store(OFF_KEY, '1')
    this.force = read(FORCE_KEY, true) === '1'
    this.offForMe = read(OFF_KEY) === '1'
  }

  async start() {
    this.adapter = pickAdapter(this.cfg.generator)
    await this.adapter.settled()
    this.root = this.adapter.contentRoot()
    installHighlightStyles()
    const frameUrl = `${this.cfg.platform}/frame/v1/?v=${encodeURIComponent(VERSION)}`
    this.ui = buildUi(frameUrl, (open) => this.bridge?.send({ type: 'yrS4:panel:toggled', open }), () => this.setOffForMe(false))
    if (this.offForMe) this.ui.setMode('minimal')
    this.bridge = new Bridge(this.ui.iframe, new URL(frameUrl).origin)
    this.bridge.on((m) => this.onFrame(m))
    this.ui.iframe.addEventListener('load', () => {
      this.bridge.markReady()
      this.sendHello()
    })
    this.bars = new MarginBars(this.ui.layer, {
      open: (id) => this.openMark(id),
      edit: (id) => this.openEditorFor(id),
      toggleOriginal: (id) => {
        if (this.edits.suppressed.has(id)) this.edits.suppressed.delete(id)
        else this.edits.suppressed.add(id)
        this.redraw(false)
      },
      remove: (id) => this.bridge.send({ type: 'yrS4:mark:delete', id }),
      removeLabel: (id, labelId) => this.removeLabelFromMark(id, labelId),
      canEdit: (m) => this.canEdit(m),
    })
    this.boxes = new BlockBoxes(this.ui.layer, (t, box, shift) => this.onBox(t, box, shift))
    this.legend = new Legend(this.ui.layer, (id) => this.focusLabel(id))
    this.toc = new TocView(this.ui.shadow)
    const tocPage = document.querySelector<HTMLElement>('[data-yrs4-toc]')
    if (tocPage) this.toc.mountInline(tocPage)
    this.popover = new LabelPopover(this.ui.layer)
    this.menu = document.createElement('div')
    this.menu.className = 'yrS4-menu'
    this.menu.hidden = true
    this.ui.layer.appendChild(this.menu)
    document.addEventListener('mousedown', (e) => {
      if (!this.menu.hidden && !e.composedPath().includes(this.menu)) this.menu.hidden = true
    })
    // Teach mode: right-click on a block opens the subjexts menu (Shift+right-click keeps the browser's menu).
    this.root.addEventListener('contextmenu', (e) => {
      if (!this.state?.teach || e.shiftKey || this.ui.mode !== 'full') return
      const b = (e.target as HTMLElement).closest?.(BLOCK_SELECTOR) as HTMLElement | null
      const t = b ? this.boxes.targets.find((x) => x.element === b) : undefined
      if (!t) return
      e.preventDefault()
      this.showMenu(t, e.pageX, e.pageY)
    })
    this.toolbar = new Toolbar(this.ui.layer, (a) => this.pick(a))
    this.headBtns = new HeadingButtons(this.ui.layer, (a, h) => this.pickHeading(a, h))
    this.rebuildText()
    this.wireSelection()
    const mo = new MutationObserver((muts) => {
      if (muts.every((m) => (m.target as Element).closest?.('[data-yrs4]'))) return
      this.scheduleRedraw(true)
    })
    mo.observe(this.root, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['class', 'open', 'style'] })
    window.addEventListener('resize', () => this.scheduleRedraw(false))
    document.addEventListener('keydown', (e) => {
      // Ctrl+Shift+S: the way in when subjexts is off for students or off for me (docs/06a-labels.qmd).
      if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === 'S' || e.key === 's')) {
        e.preventDefault()
        this.wakeUp()
        return
      }
      if ((e.target as HTMLElement)?.closest?.('input, textarea, [contenteditable]')) return
      if (this.ui.mode !== 'full') return
      if (e.key === '\\' && this.state?.teach) this.ui.openPanel(!this.ui.isOpen())
      if ((e.key === 'l' || e.key === 'L') && !e.ctrlKey && !e.metaKey && !e.altKey) this.applyCurrentLabel()
    })
    this.root.addEventListener('mouseover', (e) => {
      const t = e.target as HTMLElement
      const h = t.closest?.('h1, h2, h3, h4, h5, h6') as HTMLElement | null
      if (h && this.headings.some((x) => x.element === h)) this.hoverHeading = h
      const b = t.closest?.(BLOCK_SELECTOR) as HTMLElement | null
      this.hoverBlock = b && this.boxes.targets.some((x) => x.element === b) ? b : null
    })
    this.handleDeepLink()
  }

  private sendHello() {
    this.bridge.send({ type: 'yrS4:hello', protocol: PROTOCOL, version: VERSION, package: this.cfg.pkg, page: this.page, path: this.path, href: location.href, title: document.title, section: this.section, force: this.force, offForMe: this.offForMe })
  }

  /** Ctrl+Shift+S, or the tiny control: turn the overlay (back) on for this reader. */
  private wakeUp() {
    if (this.offForMe) {
      this.setOffForMe(false)
      return
    }
    if (this.ui.mode === 'hidden') {
      this.force = true
      store(FORCE_KEY, '1', true)
      this.sendHello()
      this.ui.toast('subjexts is off for students here. Sign in as staff to use it.')
    }
  }

  setOffForMe(off: boolean) {
    this.offForMe = off
    store(OFF_KEY, off ? '1' : null)
    this.bridge.send({ type: 'yrS4:off-for-me', off })
    if (off) {
      this.ui.setMode('minimal')
      this.clearDrawing()
    } else {
      this.ui.setMode('full')
      if (this.state) this.applyState()
    }
  }

  rebuildText() {
    this.pt = extractText(this.root, this.adapter.ignore)
    this.headings = this.adapter.headings()
    this.headBtns.attach(this.headings.map((h) => h.element), this.teachActions())
  }

  private describeOpts(): DescribeOptions {
    return { pkg: this.cfg.pkg, page: this.page, build: this.state?.build || null, adapter: this.adapter, headings: this.headings, generatedSelectors: GENERATED }
  }
  private teachActions(): ToolbarAction[] {
    if (!this.state?.signedIn || this.state.viewAsStudent) return []
    const ask = this.state.ai.tutor && this.state.ai.mode !== 'off' ? [ASK_ACTION] : []
    const chips = labelActions(this.state.labels)
    if (this.state.teach) return [...chips, TEACH_ACTIONS[3], TEACH_ACTIONS[4], ...ask]   // chips, comment, private note, ask
    if (this.state.canTeach) return [...chips, ...NOTE_ONLY, STUDENT_ACTIONS[2], ...ask]
    return [...chips, ...ask, STUDENT_ACTIONS[1], STUDENT_ACTIONS[2], STUDENT_ACTIONS[3], STUDENT_ACTIONS[4]]
  }
  private canEdit(m: MarkRow): boolean {
    return !!this.state?.userId && m.author_id === this.state.userId && !this.state.viewAsStudent
  }
  private labelById(id: string): LabelInfo | undefined {
    return this.state?.labels.find((l) => l.id === id)
  }

  /** The L key applies the current label to the selection, else the block or section under the cursor. */
  private applyCurrentLabel() {
    const id = this.state?.currentLabel
    if (!id || !this.state?.signedIn || this.state.viewAsStudent) return
    const sel = document.getSelection()
    if (sel && !sel.isCollapsed && sel.rangeCount && this.root.contains(sel.getRangeAt(0).commonAncestorContainer)) {
      this.pick({ kind: 'label', data: { labels: [id] }, label: 'current', icon: '', cls: 'labelchip' })
      return
    }
    const t = this.hoverBlock ? this.boxes.targets.find((x) => x.element === this.hoverBlock) : this.hoverHeading ? this.boxes.targets.find((x) => x.heading?.element === this.hoverHeading) : undefined
    if (t) this.toggleLabelOn(t, this.labelById(id)!)
  }

  /** The text the tutor may see around an anchor: the section, minus answers, plus a little before and after. */
  private tutorContext(anchor: Anchor) {
    const hide = (this.state?.hideFromTutor || []).join(', ')
    const textOf = (el: Element | null) => {
      if (!el) return ''
      const c = el.cloneNode(true) as Element
      c.querySelectorAll(`[data-yrs4], script, style${hide ? ', ' + hide : ''}`).forEach((x) => x.remove())
      return (c.textContent || '').replace(/\s+/g, ' ').trim()
    }
    const h = anchor.section?.id ? this.headings.find((x) => x.id === anchor.section!.id) : undefined
    const section = h ? h.section : this.root
    const sectionText = textOf(section).slice(0, 16000)
    const sameLevel = h ? this.headings.filter((x) => x.level <= h.level) : []
    const i = h ? sameLevel.indexOf(h) : -1
    const before = i > 0 ? textOf(sameLevel[i - 1].section).slice(-1500) : ''
    const after = i >= 0 && i + 1 < sameLevel.length ? textOf(sameLevel[i + 1].section).slice(0, 1500) : ''
    return { pageTitle: document.title, headingPath: anchor.section?.headings || [], sectionText, before, after }
  }

  // --- block checkboxes and the popover (D36) ---------------------------------------------------------------------
  private anchorFor(t: BlockTarget): Anchor | { error: string } {
    return t.kind === 'section' ? describeSection(t.heading!, this.describeOpts()) : describeBlock(t.element, this.pt, this.describeOpts())
  }
  /** The label marks (mine) that sit on exactly this block or section. */
  private marksOn(t: BlockTarget): Placed[] {
    return this.placed.filter((p) => p.mark.kind === 'label' && this.covers(p, t))
  }
  private covers(p: Placed, t: BlockTarget): boolean {
    if (t.kind === 'section') return p.element === t.element
    if (p.element) return false                                     // section/page scope marks don't tick blocks
    return norm(p.range.toString()) === norm(t.element.textContent || '')
  }
  private blockState(t: BlockTarget): BlockState {
    const labels: LabelInfo[] = []
    const inherited: Inherited[] = []
    const excluded: Inherited[] = []
    let partial = false
    for (const p of this.placed) {
      if (p.mark.kind !== 'label' || !p.labels?.length) continue
      if (this.covers(p, t)) {
        for (const l of p.labels) if (!labels.some((x) => x.id === l.id)) labels.push(l)
      } else if (p.element && p.element !== t.element && p.element.contains(t.element)) {
        // an enclosing section or page mark (D38)
        const a = p.mark.anchor_current || p.mark.anchor
        const from = a?.scope === 'page' ? 'the page' : `section ${a?.section?.headings.slice(-1)[0] || ''}`
        const parts = (p.mark.data.except as ExceptPart[] | undefined) || []
        for (const l of p.labels) {
          const hit = parts.some((x) => (!x.label || x.label === l.id) && this.exceptMatches(x, t))
          ;(hit ? excluded : inherited).push({ label: l, markId: p.mark.id, from })
        }
      } else if (t.kind === 'block' && !p.element && p.range.intersectsNode(t.element)) partial = true
    }
    return { labels, partial, inherited, excluded }
  }
  private exceptMatches(x: ExceptPart, t: BlockTarget): boolean {
    if (x.scope === 'section') return t.kind === 'section' && !!x.section && (x.section.id === t.heading!.id || x.section.headings.slice(-1)[0] === t.heading!.text)
    return t.kind === 'block' && !!x.quote && norm(x.quote.exact) === norm(t.element.textContent || '')
  }
  /** The exception part for a block or section, as stored in the enclosing mark. */
  private exceptPart(t: BlockTarget, label?: string): ExceptPart | { error: string } {
    if (t.kind === 'section') {
      const h = t.heading!
      const a = describeSection(h, this.describeOpts())
      return { scope: 'section', section: a.section, title: h.text, ...(label ? { label } : {}) }
    }
    const a = describeBlock(t.element, this.pt, this.describeOpts())
    if ('error' in a) return a
    const words = (t.element.textContent || '').trim().replace(/\s+/g, ' ')
    return { scope: 'block', quote: a.quote, position: a.position, title: `${t.title.toLowerCase()} “${words.slice(0, 40)}${words.length > 40 ? '…' : ''}”`, ...(label ? { label } : {}) }
  }
  /** Page-coordinate gaps for a mark's exceptions (the line is cut there). */
  private gapsFor(m: MarkRow): Placed['gaps'] {
    const parts = (m.data.except as ExceptPart[] | undefined) || []
    const out: NonNullable<Placed['gaps']> = []
    for (const x of parts) {
      let el: Element | null = null
      if (x.scope === 'section' && x.section) {
        const h = this.headings.find((y) => y.id === x.section!.id) || this.headings.find((y) => y.text === x.section!.headings.slice(-1)[0])
        el = h?.section || null
      } else if (x.quote) {
        const f = findQuote({ scope: 'block', quote: x.quote, position: x.position } as Anchor, this.pt)
        const n = f?.range.startContainer
        el = n ? (n.nodeType === 1 ? (n as Element) : n.parentElement)?.closest(BLOCK_SELECTOR) || null : null
      }
      if (!el) continue
      const r = el.getBoundingClientRect()
      out.push({ top: r.top + window.scrollY, bottom: r.bottom + window.scrollY, label: x.label })
    }
    return out
  }
  private popoverModel(t: BlockTarget): PopoverModel {
    const st = this.blockState(t)
    const mine = this.marksOn(t).some((p) => this.canEdit(p.mark))
    const editable = (x: Inherited) => !!this.marks.find((m) => m.id === x.markId && this.canEdit(m))
    return {
      title: t.kind === 'section' ? 'This section' : `This ${t.title.toLowerCase()}`,
      subtitle: t.kind === 'section' ? t.heading!.text : (t.element.textContent || '').trim().slice(0, 60),
      applied: st.labels,
      inherited: st.inherited.filter((x) => !st.excluded.some((e) => e.markId === x.markId && e.label.id === x.label.id)),
      excluded: st.excluded,
      choices: this.state?.labels || [],
      canCreate: !!this.state?.signedIn,
      canRemove: mine || st.inherited.some(editable) || st.excluded.some(editable),
      canEditText: !!this.state?.teach && t.kind === 'block',
      hasEdit: t.element.hasAttribute('data-yrs4-edit'),
    }
  }
  /** The in-place editor (D40): the block's Markdown goes to the frame, where the teacher edits it. */
  private startEdit(t: BlockTarget) {
    if (!this.state?.signedIn) return this.ui.openPanel(true)
    const existing = t.element.getAttribute('data-yrs4-edit')
    if (existing) return this.openEditorFor(existing)
    const a = describeBlock(t.element, this.pt, this.describeOpts())
    if ('error' in a) return this.ui.toast(a.error)
    const md = htmlToMarkdown(t.element)
    this.popover.hide()
    const draftKey = Math.random().toString(36).slice(2)
    const tag = t.element.tagName.toLowerCase()
    this.editor.open(t.element, {
      title: t.title,
      markdown: md,
      render: (text) => this.renderMd(text),
      onDraft: (text) => this.bridge.send({ type: 'yrS4:edit:draft', markId: this.draftIds.get(draftKey), draftKey, anchor: a, original_md: md, md: text, block_tag: tag }),
      onSave: (text) => this.bridge.send({ type: 'yrS4:edit:save', markId: this.draftIds.get(draftKey), anchor: a, original_md: md, md: text, block_tag: tag }),
      onCancel: () => {
        const id = this.draftIds.get(draftKey)
        if (id) this.bridge.send({ type: 'yrS4:edit:discard', markId: id })
        this.redraw(false)
      },
    })
  }
  /** Edit an existing in-place edit where it shows. */
  private openEditorFor(id: string) {
    const m = this.marks.find((x) => x.id === id)
    const el = this.edits.elementOf(id) || this.edits.lastElementOf(id)
    if (!m || !el || !m.anchor) return this.ui.toast('That edit is not on this page.')
    this.bars.hideCard()
    this.edits.restore(id)
    const draft = typeof m.data.draft_md === 'string' ? m.data.draft_md : null
    const base = m.body || String(m.data.original_md || '')
    this.editor.open(el, {
      title: m.data.draft && !m.body ? 'My edit (draft)' : 'My edit',
      markdown: draft ?? base,
      draftNote: draft !== null && draft !== base ? 'resumed from an unsaved draft' : '',
      render: (text) => this.renderMd(text),
      onDraft: (text) => this.bridge.send({ type: 'yrS4:edit:draft', markId: id, draftKey: id, anchor: m.anchor!, original_md: String(m.data.original_md || ''), md: text }),
      onSave: (text) => this.bridge.send({ type: 'yrS4:edit:save', markId: id, anchor: m.anchor!, original_md: String(m.data.original_md || ''), md: text }),
      onCancel: () => {
        this.bridge.send({ type: 'yrS4:edit:discard', markId: id })
        this.redraw(false)
      },
    })
  }
  /** Markdown → sanitized HTML, by the frame. */
  private renderMd(md: string): Promise<string> {
    const id = Math.random().toString(36).slice(2)
    return new Promise((resolve) => {
      this.renderWaiters.set(id, resolve)
      this.bridge.send({ type: 'yrS4:md:render', id, md })
      setTimeout(() => {
        if (this.renderWaiters.delete(id)) resolve('<em>(no preview)</em>')
      }, 5000)
    })
  }
  private showMenu(t: BlockTarget, x: number, y: number) {
    const m = this.menu
    m.replaceChildren()
    const add = (text: string, fn: () => void) => {
      const b = document.createElement('button')
      b.type = 'button'
      b.textContent = text
      b.addEventListener('click', () => {
        m.hidden = true
        fn()
      })
      m.appendChild(b)
    }
    const hasEdit = t.element.hasAttribute('data-yrs4-edit')
    add(hasEdit ? '✎ Edit my edit of this text' : '✎ Edit this text…', () => this.startEdit(t))
    add('● Label this block…', () => {
      const box = this.boxes.boxFor(t.element)
      this.openPopover(t, box ? box.getBoundingClientRect() : new DOMRect(x - window.scrollX, y - window.scrollY, 1, 1))
    })
    const cur = this.state?.currentLabel ? this.labelById(this.state.currentLabel) : undefined
    if (cur) add(`${this.blockState(t).labels.some((l) => l.id === cur.id) ? 'Remove' : 'Apply'} "${cur.name}"`, () => this.toggleLabelOn(t, cur))
    const hint = document.createElement('div')
    hint.className = 'yrS4-menu-hint'
    hint.textContent = `${t.title} · Shift+right-click for the browser menu`
    m.appendChild(hint)
    m.hidden = false
    const w = m.offsetWidth || 220
    m.style.left = `${Math.min(x, window.scrollX + document.documentElement.clientWidth - w - 8)}px`
    m.style.top = `${y}px`
  }
  private setExcept(t: BlockTarget, markId: string, l: LabelInfo, add: boolean) {
    const m = this.marks.find((x) => x.id === markId)
    if (!m) return
    const several = ((m.data.labels as string[]) || []).length > 1
    const part = this.exceptPart(t, several ? l.id : undefined)
    if ('error' in part) return this.ui.toast(part.error)
    this.bridge.send({ type: 'yrS4:mark:except', id: markId, part, add })
  }
  private onBox(t: BlockTarget, box: HTMLElement, shift: boolean) {
    if (!this.state?.signedIn) {
      this.ui.openPanel(true)
      this.ui.toast('Sign in to label passages.')
      return
    }
    const cur = this.state.currentLabel ? this.labelById(this.state.currentLabel) : undefined
    if (shift && cur) {
      this.toggleLabelOn(t, cur)
      return
    }
    if (this.popover.visible && this.popTarget?.element === t.element) {
      this.popover.hide()
      return
    }
    this.openPopover(t, box.getBoundingClientRect())
  }
  private openPopover(t: BlockTarget, rect: DOMRect) {
    this.popTarget = t
    this.popover.show(rect, this.popoverModel(t), {
      add: (l) => this.addLabelOn(t, l),
      remove: (l) => this.removeLabelOn(t, l),
      except: (markId, l) => this.setExcept(t, markId, l, true),
      include: (markId, l) => this.setExcept(t, markId, l, false),
      create: (name) => {
        const a = this.anchorFor(t)
        if ('error' in a) return this.ui.toast(a.error)
        this.bridge.send({ type: 'yrS4:label:create', name, anchor: a, quoteText: a.quote?.exact })
      },
      close: () => { this.popTarget = null },
      editText: () => this.startEdit(t),
    })
  }
  private toggleLabelOn(t: BlockTarget, l: LabelInfo) {
    const has = this.blockState(t).labels.some((x) => x.id === l.id)
    if (has) this.removeLabelOn(t, l)
    else this.addLabelOn(t, l)
  }
  private addLabelOn(t: BlockTarget, l: LabelInfo) {
    const own = this.marksOn(t).find((p) => this.canEdit(p.mark))
    if (own) {
      const ids = (own.mark.data.labels as string[]) || []
      if (!ids.includes(l.id)) this.bridge.send({ type: 'yrS4:mark:labels', id: own.mark.id, labels: [...ids, l.id] })
      return
    }
    const a = this.anchorFor(t)
    if ('error' in a) return this.ui.toast(a.error)
    this.bridge.send({ type: 'yrS4:mark:create', kind: 'label', anchor: a, quoteText: a.quote?.exact, data: { labels: [l.id] } })
  }
  private removeLabelOn(t: BlockTarget, l: LabelInfo) {
    for (const p of this.marksOn(t)) {
      if (!this.canEdit(p.mark)) continue
      const ids = (p.mark.data.labels as string[]) || []
      if (ids.includes(l.id)) this.removeLabelFromMark(p.mark.id, l.id)
    }
  }
  private removeLabelFromMark(id: string, labelId: string) {
    const m = this.marks.find((x) => x.id === id)
    if (!m) return
    const ids = ((m.data.labels as string[]) || []).filter((x) => x !== labelId)
    this.bridge.send({ type: 'yrS4:mark:labels', id, labels: ids })
  }
  private focusLabel(id: string | null) {
    const layer = this.ui.layer
    if (!id) {
      layer.removeAttribute('data-focus')
      layer.querySelectorAll('.yrS4-bar.yrS4-focus').forEach((b) => b.classList.remove('yrS4-focus'))
      return
    }
    layer.setAttribute('data-focus', id)
    layer.querySelectorAll<HTMLElement>('.yrS4-bar').forEach((b) => b.classList.toggle('yrS4-focus', (b.getAttribute('data-labels') || '').split(' ').includes(id)))
  }

  // --- selection and toolbar -------------------------------------------------------------------------------------
  private wireSelection() {
    const maybeShow = () => {
      if (this.ui.mode !== 'full') return
      const sel = document.getSelection()
      if (!sel || sel.isCollapsed || sel.rangeCount === 0) {
        this.toolbar.hide()
        return
      }
      const range = sel.getRangeAt(0)
      if (!this.root.contains(range.commonAncestorContainer)) {
        this.toolbar.hide()
        return
      }
      const actions = this.teachActions()
      if (!actions.length) return
      this.toolbar.setActions(actions)
      const rect = range.getBoundingClientRect()
      this.toolbar.showAt(rect)
    }
    document.addEventListener('mouseup', () => setTimeout(maybeShow, 10))
    document.addEventListener('keyup', (e) => {
      if (e.shiftKey || e.key === 'Shift') setTimeout(maybeShow, 10)
    })
    document.addEventListener('selectionchange', () => {
      const sel = document.getSelection()
      if (!sel || sel.isCollapsed) this.toolbar.hide()
    })
    document.addEventListener('touchend', () => setTimeout(maybeShow, 300))
  }

  private pick(a: ToolbarAction) {
    const sel = document.getSelection()
    if (!sel || sel.rangeCount === 0) return
    const range = sel.getRangeAt(0)
    const anchor = describeRange(range, this.pt, this.describeOpts())
    this.toolbar.hide()
    if ('error' in anchor) {
      this.ui.toast(anchor.error)
      return
    }
    this.create(a, anchor)
  }

  private pickHeading(a: ToolbarAction, hEl: HTMLElement) {
    const h = this.headings.find((x) => x.element === hEl)
    if (!h) return
    this.create(a, describeSection(h, this.describeOpts()))
  }

  markPage(a: ToolbarAction) {
    this.create(a, describePage(this.describeOpts(), document.title))
  }

  private create(a: ToolbarAction, anchor: Anchor) {
    if (a.kind === 'ask') {
      const code = anchor.block?.kind === 'code'
      this.bridge.send({ type: 'yrS4:ask', anchor, action: anchor.scope === 'section' ? 'summarize' : code ? 'explain-code' : 'ask', passage: anchor.quote?.exact || null, context: this.tutorContext(anchor) })
      this.ui.openPanel(true)
      document.getSelection()?.removeAllRanges()
      return
    }
    this.pendingAnchor = anchor
    this.bridge.send({ type: 'yrS4:mark:create', kind: a.kind, anchor, status: a.status, quoteText: anchor.quote?.exact, data: a.data })
    if (a.kind !== 'coverage' && a.kind !== 'reaction' && !a.data?.highlight && !(a.kind === 'label' && (a.data?.labels as string[] | undefined)?.length)) this.ui.openPanel(true)   // comments, notes and messages are typed in the frame
    document.getSelection()?.removeAllRanges()
  }

  // --- frame messages ----------------------------------------------------------------------------------------------
  private onFrame(m: FrameToPage) {
    switch (m.type) {
      case 'yrS4:kill':
        this.clearDrawing()
        this.ui.host.remove()
        return
      case 'yrS4:state':
        this.state = m.state
        this.applyState()
        return
      case 'yrS4:marks':
        for (const mk of m.marks) if (mk.anchor_current && this.reattached.has(mk.id)) this.reattached.delete(mk.id)
        this.marks = m.marks
        this.redraw(true)
        if (this.popover.visible && this.popTarget) this.popover.update(this.popoverModel(this.popTarget))
        this.bars.refreshCard()
        return
      case 'yrS4:pages':
        this.pageCoverage = m.coverage
        this.sidebarDots()
        return
      case 'yrS4:activity':
        this.activity = m.items
        this.drawActivity()
        return
      case 'yrS4:panel':
        this.ui.openPanel(m.open)
        return
      case 'yrS4:goto':
        this.goto(m.id)
        return
      case 'yrS4:toast':
        this.ui.toast(m.text, m.undo ? () => this.bridge.send({ type: 'yrS4:mark:delete', id: m.undo! }) : undefined)
        return
      case 'yrS4:off-for-me':
        if (m.off !== this.offForMe) this.setOffForMe(m.off)
        return
      case 'yrS4:md:html': {
        const w = this.renderWaiters.get(m.id)
        if (w) {
          this.renderWaiters.delete(m.id)
          w(m.html)
        }
        return
      }
      case 'yrS4:edit:open':
        this.openEditorFor(m.id)
        return
      case 'yrS4:edit:drafted':
        this.draftIds.set(m.draftKey, m.markId)
        return
      case 'yrS4:toc': {
        // The list's links are site-relative paths. The base is the published site when we are on it; on a
        // preview (localhost), it is this page's address minus this page's own path under the site.
        const site = (m.site || '').replace(/\/?$/, '/')
        const href = location.href.split(/[?#]/)[0]
        let base = site && href.startsWith(site) ? site : ''
        if (!base) {
          const own = m.currentPath || this.path.split('/').pop() || ''
          const i = own ? href.lastIndexOf(own) : -1
          base = i > 0 && href.slice(i) === own ? href.slice(0, i) : site || href.slice(0, href.lastIndexOf('/') + 1)
        }
        if (m.open) this.toc.show({ base, labels: m.labels, entries: m.entries })
        return
      }
    }
  }

  private clearDrawing() {
    this.painter.clear()
    this.bars.clear()
    this.boxes.clear()
    this.legend.remove()
    this.showTocPageEntry(false)
    this.editor.close()
    this.edits.restoreAll()
    this.menu.hidden = true
    this.toc.hide()
    this.tocLink?.remove()
    this.tocLink = null
    this.popover.hide()
    this.toolbar.hide()
    this.headBtns.hide()
    this.activityLayer?.replaceChildren()
    this.placed = []
    this.sidebarDots()
  }

  private applyState() {
    const s = this.state!
    if (s.disabled) return
    if (s.page) this.page = s.page
    if (this.offForMe) {
      this.ui.setMode('minimal')
      this.clearDrawing()
      return
    }
    if (s.hidden) {
      // Off for students and the reader isn't staff: nothing at all, unless they asked (?subjexts=on, Ctrl+Shift+S).
      if (!this.force) {
        this.ui.setMode('hidden')
        this.clearDrawing()
        return
      }
      this.ui.setMode('full')
      this.clearDrawing()
      this.ui.setFab('subjexts', { text: 'off for students', off: true })
      return
    }
    this.ui.setMode('full')
    const badge = s.viewAsStudent ? { text: `student view · ${s.section?.name || ''}`.trim() } : s.teach ? { text: 'Teach', teach: true } : s.section ? { text: s.section.name } : null
    this.ui.setFab('subjexts', badge)
    this.headBtns.attach(this.headings.map((h) => h.element), this.teachActions())
    this.headBtns.setEnabled(false)                                   // replaced by the section checkboxes (D36)
    this.boxes.setEnabled(s.teach)
    this.injectTocLink(s.hasLabels && !this.toc.isInline && !this.bookHasTocPage())
    this.showTocPageEntry(s.hasLabels)
    if (this.toc.isInline || location.hash.includes('yrS4-toc')) this.bridge.send({ type: 'yrS4:toc:get' })
    this.redraw(false)
  }
  /** The book's own "Table of contents by label" page: its sidebar entry is hidden until a label exists (and
   *  whenever the overlay draws nothing), and the page itself explains what it is for while it is empty. */
  private showTocPageEntry(show: boolean) {
    for (const [path, a] of this.adapter.sidebarLinks()) {
      if (!/subjexts-labels/.test(path)) continue
      const li = a.closest('li') || a
      ;(li as HTMLElement).style.display = show ? '' : 'none'
    }
    if (this.toc.isInline && !show) this.toc.showEmpty()
  }
  /** Does the book's own sidebar already list the table-of-contents page? */
  private bookHasTocPage(): boolean {
    for (const [path] of this.adapter.sidebarLinks()) if (/subjexts-labels/.test(path)) return true
    return false
  }

  /** "Table of contents by label" at the top of the book's own sidebar (D39). */
  private tocLink: HTMLElement | null = null
  private injectTocLink(show: boolean) {
    if (!show) {
      this.tocLink?.remove()
      this.tocLink = null
      return
    }
    if (this.tocLink?.isConnected) return
    const first = this.adapter.sidebarLinks().values().next().value as HTMLElement | undefined
    const li = first?.closest('li')
    if (!first || !li) return
    const item = document.createElement('li')
    item.className = li.className
    item.setAttribute('data-yrs4', '')
    const a = document.createElement('a')
    a.className = first.className
    a.href = '#yrS4-toc'
    a.textContent = 'Table of contents by label'
    a.title = 'Every place in the book that carries a label'
    a.addEventListener('click', (e) => {
      e.preventDefault()
      this.bridge.send({ type: 'yrS4:toc:get' })
    })
    item.appendChild(a)
    li.parentElement?.insertBefore(item, li)
    this.tocLink = item
  }

  private openMark(id: string) {
    this.bridge.send({ type: 'yrS4:mark:open', id })
    this.ui.openPanel(true)
  }

  // --- drawing ----------------------------------------------------------------------------------------------------
  private scheduleRedraw(textChanged: boolean) {
    if (this.redrawTimer) clearTimeout(this.redrawTimer)
    this.redrawTimer = window.setTimeout(() => this.redraw(textChanged), 120)
  }

  redraw(textChanged: boolean) {
    try {
      if (textChanged) this.rebuildText()
      if (this.ui.mode !== 'full' || this.state?.hidden) return
      this.painter.clear()
      const placed: Placed[] = []
      const orphans: string[] = []
      let reattachChanged = false
      const showNotes = !!this.state?.showNotes
      const keptEdits = new Set<string>()
      for (const m of this.marks) {
        if (m.kind === 'author_note' && !showNotes) continue
        if (m.kind === 'student_note' && m.author_id !== this.state?.userId) continue
        if (m.kind === 'message' || m.kind === 'reaction') continue
        if (m.kind === 'suggestion') {
          // an in-place edit (D40): the viewer's own, shown in place of its block
          if (!this.state?.showEdits || m.author_id !== this.state.userId || this.state.viewAsStudent) continue
          const html = m.data.proposed_html as string | undefined
          if (!html && !m.data.draft) continue
          let el = this.edits.elementOf(m.id) || this.edits.lastElementOf(m.id)
          if (!el) {
            const a = m.anchor_current || m.anchor
            const f = a?.quote ? findQuote(a, this.pt) : null
            const n = f?.range.startContainer
            el = n ? ((n.nodeType === 1 ? (n as Element) : n.parentElement)?.closest(BLOCK_SELECTOR) as HTMLElement | null) || undefined : undefined
          }
          if (!el || (el.hasAttribute('data-yrs4-edit') && el.getAttribute('data-yrs4-edit') !== m.id)) {
            orphans.push(m.id)
            continue
          }
          if (this.editor.isOpen && this.editor.element === el) { keptEdits.add(m.id); continue }
          if (!html) {
            // a draft only: nothing replaces the block; its line says "draft" and the card's Edit resumes it
            this.edits.restore(m.id)
            const range0 = document.createRange()
            range0.selectNodeContents(el)
            placed.push({ mark: m, range: range0, cls: 'edit', element: el })
            continue
          }
          if (this.edits.suppressed.has(m.id)) this.edits.restore(m.id)
          else this.edits.apply(m.id, el, html)
          keptEdits.add(m.id)
          const range = document.createRange()
          range.selectNodeContents(el)
          placed.push({ mark: m, range, cls: 'edit', element: el })
          continue
        }
        const cls = paintClassFor(m.kind, m.data)
        if (!cls) continue
        const anchor = m.anchor_current || m.anchor
        if (!anchor) continue
        let found = findAnchor(anchor, this.pt, this.headings)
        if (!found && anchor.quote) {
          const hit = fuzzyFind(anchor, this.pt.text)
          const range = hit && rangeFor(this.pt, hit.start, hit.end)
          if (hit && range) {
            found = { range, start: hit.start, end: hit.end, how: 'exact' }
            if (!this.reattached.has(m.id)) {
              const cand = describeRange(range, this.pt, this.describeOpts())
              if (!('error' in cand)) {
                this.reattached.set(m.id, { ...cand, scope: anchor.scope, build: this.state?.build || 'local', score: hit.score } as Anchor)
                reattachChanged = true
              }
            }
          }
        }
        if (!found) {
          orphans.push(m.id)
          continue
        }
        const labels = m.kind === 'label' ? ((m.data.labels as string[]) || []).map((id) => this.labelById(id)).filter((l): l is LabelInfo => !!l) : undefined
        placed.push({ mark: m, range: found.range, cls, element: found.element, labels, gaps: m.kind === 'label' && m.data.except ? this.gapsFor(m) : undefined })
      }
      this.edits.keep(keptEdits)
      // marks inside a block that currently shows an edit can't be found (the text changed): not orphans
      const editedTexts = [...keptEdits].map((id) => this.edits.originalTextOf(id)).filter(Boolean)
      const realOrphans = orphans.filter((id) => {
        const m = this.marks.find((x) => x.id === id)
        const q = (m?.anchor_current || m?.anchor)?.quote?.exact
        return !(q && editedTexts.some((t) => t.includes(norm(q))))
      })
      orphans.length = 0
      orphans.push(...realOrphans)
      if (this.flashRange) this.painter.paint(new Map<PaintClass, Range[]>([['flash', [this.flashRange]]]))
      this.placed = placed
      this.bars.layout(placed, this.root)
      this.boxes.layout(findBlocks(this.root, this.headings), this.root, (t) => this.blockState(t))
      this.legend.render(legendItems(placed), this.root)
      this.badgeContainers(placed)
      if (this.activity.length) this.drawActivity()
      if (orphans.join() !== this.orphans.join()) {
        this.orphans = orphans
        this.bridge.send({ type: 'yrS4:orphans', ids: orphans })
      }
      if (reattachChanged) {
        this.bridge.send({ type: 'yrS4:reattach', items: [...this.reattached].map(([id, anchor_current]) => ({ id, anchor_current })) })
      }
      this.sidebarDots()
    } catch (e) {
      this.report(e)
    }
  }

  /** A closed callout/tabset/details with a mark inside gets a small dot on its header. */
  private badgeContainers(placed: Placed[]) {
    for (const c of this.adapter.containers()) {
      const old = c.header.querySelector(':scope > .yrS4-dot')
      let color: string | null = null
      for (const p of placed) {
        if (p.element ? c.element.contains(p.element) || p.element.contains(c.element) : c.element.contains(p.range.commonAncestorContainer)) {
          if (!c.isOpen()) color = colorsOf(p)[0]
        }
      }
      if (color && !c.isOpen()) {
        const dot = old || document.createElement('span')
        dot.className = 'yrS4-dot'
        dot.setAttribute('data-yrs4', '')
        dot.setAttribute('title', 'There is a mark inside')
        ;(dot as HTMLElement).style.cssText = `display:inline-block;width:9px;height:9px;border-radius:50%;margin-left:6px;vertical-align:middle;background:${color}`
        if (!old) c.header.appendChild(dot)
      } else if (old) old.remove()
    }
  }

  /** Staff's "class activity": reaction counts as small badges beside the passages (docs/08-ai-tutor.qmd). */
  private drawActivity() {
    try {
      if (!this.activityLayer) {
        this.activityLayer = document.createElement('div')
        this.activityLayer.className = 'yrS4-activity'
        this.ui.layer.appendChild(this.activityLayer)
      }
      this.activityLayer.replaceChildren()
      const rootRect = this.root.getBoundingClientRect()
      for (const it of this.activity) {
        const found = findAnchor(it.anchor, this.pt, this.headings)
        if (!found) continue
        const rects = found.element ? [found.element.getBoundingClientRect()] : Array.from(found.range.getClientRects())
        if (!rects.length) continue
        const top = Math.min(...rects.map((r) => r.top)) + window.scrollY
        const b = document.createElement('span')
        b.textContent = `${it.emoji} ${it.n}`
        b.title = `${it.n} student${it.n === 1 ? '' : 's'}: ${it.label}`
        b.style.cssText = `position:absolute;left:${rootRect.right + window.scrollX + 6}px;top:${top}px;font:12px system-ui,sans-serif;background:#fff3cd;border:1px solid #f0c36d;border-radius:10px;padding:0 6px;white-space:nowrap`
        this.activityLayer.appendChild(b)
      }
    } catch (e) {
      this.report(e)
    }
  }

  /** Coverage dots in the book's own table of contents (docs/06-coverage.qmd). */
  private sidebarDots() {
    try {
      const links = this.adapter.sidebarLinks()
      for (const [path, a] of links) {
        // the link's path may carry a base folder (the site's, or a preview's): match by the longest tail
        const segs = path.split('/').filter(Boolean)
        let status: 'full' | 'partial' | undefined
        for (let i = 0; i < segs.length && !status; i++) status = this.pageCoverage[canonicalPageId(segs.slice(i).join('/'), this.state?.versionSuffix)]
        let dot = a.querySelector<HTMLElement>(':scope > .yrS4-dot')
        if (!status || this.ui.mode !== 'full') {
          dot?.remove()
          continue
        }
        if (!dot) {
          dot = document.createElement('span')
          dot.className = 'yrS4-dot'
          dot.setAttribute('data-yrs4', '')
          a.appendChild(dot)
        }
        dot.title = status === 'full' ? 'Covered' : 'Partly covered'
        dot.style.cssText = `display:inline-block;width:8px;height:8px;border-radius:50%;margin-left:6px;vertical-align:middle;border:1.5px solid #43a047;background:${status === 'full' ? '#43a047' : 'linear-gradient(90deg,#43a047 50%,transparent 50%)'}`
      }
    } catch (e) {
      this.report(e)
    }
  }

  private flashRange: Range | null = null
  private goto(id: string) {
    const p = this.placed.find((x) => x.mark.id === id)
    if (!p) {
      this.ui.toast('That passage can\'t be found on this page any more.')
      return
    }
    // open containers around it
    for (const c of this.adapter.containers()) {
      const inside = p.element ? c.element.contains(p.element) : c.element.contains(p.range.commonAncestorContainer)
      if (inside && !c.isOpen()) c.open()
    }
    setTimeout(() => {
      const target = p.element || p.range.startContainer.parentElement
      target?.scrollIntoView({ behavior: 'smooth', block: 'center' })
      this.flashRange = p.element ? null : p.range.cloneRange()
      if (p.element) {
        p.element.style.transition = 'background-color .3s'
        p.element.style.backgroundColor = 'rgba(255,193,7,.35)'
        setTimeout(() => { p.element!.style.backgroundColor = '' }, 1500)
      }
      this.redraw(false)
      setTimeout(() => {
        this.flashRange = null
        this.redraw(false)
      }, 1800)
    }, 150)
  }

  /**
   * `#yrS4=<mark id>` opens the page at a mark (a link from the panel's lists, a note packet, a message).
   * `&yrS4-tab=notes` reopens the panel on the Editorial notes tab once the jump lands. A hidden editorial note
   * (or edit) is switched on, through the frame, so that the jump can land; if the mark never appears, say so.
   */
  private handleDeepLink() {
    const m = /(?:^|[#&])yrS4=([0-9a-f-]{36})/.exec(location.hash)
    if (!m) return
    const id = m[1]
    const tab = /(?:^|[#&])yrS4-tab=notes(?:&|$)/.test(location.hash)
    let askedToShow = false
    const tryGo = (n: number) => {
      if (this.placed.some((p) => p.mark.id === id)) {
        this.goto(id)
        if (tab) {
          this.ui.openPanel(true)
          this.bridge.send({ type: 'yrS4:view', view: 'notes' })
        }
        return
      }
      const mk = this.marks.find((x) => x.id === id)
      if (mk && !askedToShow && ((mk.kind === 'author_note' && !this.state?.showNotes) || (mk.kind === 'suggestion' && !this.state?.showEdits))) {
        askedToShow = true
        this.bridge.send({ type: 'yrS4:show-notes', on: true })
      }
      if (n > 0) setTimeout(() => tryGo(n - 1), 500)
      else this.ui.toast('That passage can\'t be found on this page any more.')
    }
    tryGo(20)
  }

  report(e: unknown) {
    console.error('[yrS4]', e)
    try {
      this.bridge?.send({ type: 'yrS4:error', message: e instanceof Error ? e.message : String(e), stack: e instanceof Error ? e.stack : undefined })
    } catch { /* ignore */ }
  }
}

;(function main() {
  const w = window as unknown as { __yrS4?: Overlay }
  if (w.__yrS4) return
  const cfg = readConfig()
  if (!cfg) {
    console.warn('[yrS4] no data-package on the script tag; nothing to do')
    return
  }
  const o = new Overlay(cfg)
  w.__yrS4 = o
  o.start().catch((e) => o.report(e))
})()
