// Rendered block → Markdown, for the in-place editor (docs/07-author-notes.qmd "In-place edits", D40). Good
// enough to give the teacher something to edit and the AI something to compare; the book's real source
// (callouts, cross-references, shortcodes) may differ, and the AI applying the proposal reads that source.

const SKIP = '[data-yrs4], .header-section-number, .chapter-number, .anchorjs-link, .headerlink, .code-copy-button, .code-tools-button, button, script, style'

function text(n: Node): string {
  return (n.textContent || '').replace(/\s+/g, ' ')
}

function inline(node: Node): string {
  if (node.nodeType === Node.TEXT_NODE) return (node.textContent || '').replace(/\s+/g, ' ')
  if (node.nodeType !== Node.ELEMENT_NODE) return ''
  const el = node as HTMLElement
  if (el.matches(SKIP)) return ''
  const inner = () => Array.from(el.childNodes).map(inline).join('')
  switch (el.tagName.toLowerCase()) {
    case 'strong': case 'b': return `**${inner().trim()}**`
    case 'em': case 'i': return `*${inner().trim()}*`
    case 'code': return '`' + text(el).trim() + '`'
    case 'a': {
      const href = el.getAttribute('href') || ''
      const t = inner().trim()
      return href && !href.startsWith('#') ? `[${t}](${href})` : t
    }
    case 'br': return '  \n'
    case 'img': return `![${el.getAttribute('alt') || ''}](${el.getAttribute('src') || ''})`
    case 'sup': return `^${inner().trim()}^`
    case 'sub': return `~${inner().trim()}~`
    case 'del': case 's': return `~~${inner().trim()}~~`
    case 'kbd': return '`' + text(el).trim() + '`'
    default: return inner()
  }
}

function list(el: HTMLElement, indent: string): string {
  const ordered = el.tagName.toLowerCase() === 'ol'
  let n = Number(el.getAttribute('start') || 1)
  const out: string[] = []
  for (const li of Array.from(el.children)) {
    if (li.tagName.toLowerCase() !== 'li') continue
    const marker = ordered ? `${n++}. ` : '- '
    const parts: string[] = []
    let first = ''
    for (const c of Array.from(li.childNodes)) {
      if (c.nodeType === Node.ELEMENT_NODE && /^(ul|ol)$/i.test((c as Element).tagName)) parts.push(list(c as HTMLElement, indent + '  '))
      else if (c.nodeType === Node.ELEMENT_NODE && /^(p|div)$/i.test((c as Element).tagName)) first += (first ? '\n\n' + indent + '  ' : '') + inline(c).trim()
      else first += inline(c)
    }
    out.push(indent + marker + first.trim() + (parts.length ? '\n' + parts.join('\n') : ''))
  }
  return out.join('\n')
}

/** The Markdown for one block element (paragraph, list, code block, table, quote, heading). */
export function htmlToMarkdown(el: HTMLElement): string {
  const tag = el.tagName.toLowerCase()
  if (el.matches('pre, div.cell, div.cell_input, div.highlight, div.sourceCode')) {
    const code = el.querySelector('code') || el.querySelector('pre') || el
    const lang = Array.from(code.classList).concat(Array.from(el.classList)).map((c) => c.replace(/^(language-|sourceCode\s*)/, '')).find((c) => /^[a-z0-9+#-]{1,20}$/i.test(c) && !['sourceCode', 'cell', 'highlight', 'code'].includes(c)) || ''
    return '```' + lang + '\n' + (code.textContent || '').replace(/\n$/, '') + '\n```'
  }
  if (tag === 'ul' || tag === 'ol') return list(el, '')
  if (/^h[1-6]$/.test(tag)) {
    const clone = el.cloneNode(true) as HTMLElement
    clone.querySelectorAll(SKIP).forEach((x) => x.remove())
    return '#'.repeat(Number(tag[1])) + ' ' + inline(clone).trim()
  }
  if (tag === 'blockquote') return Array.from(el.children).map((c) => '> ' + htmlToMarkdown(c as HTMLElement).replace(/\n/g, '\n> ')).join('\n>\n')
  if (tag === 'table') {
    const rows = Array.from(el.querySelectorAll('tr'))
    const cells = (tr: Element) => Array.from(tr.children).map((c) => inline(c).trim().replace(/\|/g, '\\|'))
    if (!rows.length) return ''
    const head = cells(rows[0])
    const out = ['| ' + head.join(' | ') + ' |', '| ' + head.map(() => '---').join(' | ') + ' |']
    for (const r of rows.slice(1)) out.push('| ' + cells(r).join(' | ') + ' |')
    return out.join('\n')
  }
  if (tag === 'figure') {
    const img = el.querySelector('img')
    const cap = el.querySelector('figcaption')
    return img ? `![${cap ? inline(cap).trim() : img.getAttribute('alt') || ''}](${img.getAttribute('src') || ''})` : inline(el).trim()
  }
  return inline(el).trim()
}
