// The legend (docs/06a-labels.qmd, D36): a small strip at the top of a page that has marks, listing the labels
// (and other kinds of marks) on the page with their colors. Collapsible to one tiny control; the choice is
// remembered for the whole book (this origin's storage). It lives in the page's DOM so it flows with the text,
// marked data-yrs4 so the overlay ignores it, with its own style element in the document head.
import type { LabelInfo } from '../../../shared/types.ts'
import { KIND_COLORS, type Placed } from './margin.ts'

const KEY = 'yrS4-legend-collapsed'
const STYLE_ID = 'yrS4-legend-style'
const KIND_NAMES: Record<string, string> = { comment: 'Comment', note: 'Editorial note', student: 'My highlight', edit: 'My edit', covered: 'Covered', assigned: 'Read on your own', skipped: 'Skipped in class' }

export interface LegendItem { id: string; name: string; color: string; dotted?: boolean; n: number }

export function legendItems(placed: Placed[]): LegendItem[] {
  const by = new Map<string, LegendItem>()
  for (const p of placed) {
    if (p.cls === 'flash') continue
    if (p.mark.kind === 'label' && !p.labels?.length) continue   // a label the viewer can't see (or a deleted one)
    if (p.labels?.length) {
      for (const l of p.labels) {
        const it = by.get(l.id) || { id: l.id, name: l.name, color: l.color, dotted: l.style === 'dotted', n: 0 }
        it.n++
        by.set(l.id, it)
      }
    } else {
      const it = by.get(p.cls) || { id: p.cls, name: KIND_NAMES[p.cls] || p.cls, color: KIND_COLORS[p.cls] || '#9ca3af', dotted: p.cls === 'note', n: 0 }
      it.n++
      by.set(p.cls, it)
    }
  }
  return [...by.values()].sort((a, b) => b.n - a.n || a.name.localeCompare(b.name))
}

export class Legend {
  private el: HTMLElement | null = null
  private collapsed: boolean
  constructor(private layer: HTMLElement, private onHover: (id: string | null) => void) {
    let c = false
    try {
      c = localStorage.getItem(KEY) === '1'
    } catch { /* ignore */ }
    this.collapsed = c
    this.installStyle()
  }

  private installStyle() {
    if (document.getElementById(STYLE_ID)) return
    const s = document.createElement('style')
    s.id = STYLE_ID
    s.setAttribute('data-yrs4', '')
    s.textContent = `
.yrS4-legend { font: 12px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; color: #374151; background: #f8fafc; border: 1px solid #e2e8f0; border-left: 3px solid #94a3b8; border-radius: 6px; padding: 4px 10px; margin: 0 0 14px; display: flex; flex-wrap: wrap; align-items: center; gap: 4px 14px; }
.yrS4-legend.collapsed { display: inline-flex; padding: 1px 8px; background: transparent; border-color: #e2e8f0; border-left-width: 1px; font-size: 11px; color: #6b7280; }
.yrS4-legend-title { font-weight: 600; color: #475569; }
.yrS4-legend-item { display: inline-flex; align-items: center; gap: 6px; cursor: default; }
.yrS4-legend-line { display: inline-block; width: 3px; height: 14px; border-radius: 2px; background: var(--c); }
.yrS4-legend-line.dotted { background: repeating-linear-gradient(0deg, var(--c) 0 3px, transparent 3px 5px); }
.yrS4-legend-n { color: #94a3b8; }
.yrS4-legend-toggle { margin-left: auto; border: 0; background: transparent; color: #64748b; cursor: pointer; font: inherit; font-size: 11px; padding: 0 2px; }
.yrS4-legend-toggle:hover { color: #1f2937; text-decoration: underline; }
@media (prefers-color-scheme: dark) { .yrS4-legend { background: #1f2937; border-color: #374151; color: #d1d5db; } .yrS4-legend-title { color: #e5e7eb; } .yrS4-legend-toggle { color: #9ca3af; } .yrS4-legend-toggle:hover { color: #f3f4f6; } }
@media print { .yrS4-legend-toggle { display: none; } }
`
    document.head.appendChild(s)
  }

  /** Where the legend goes: the very top of the page's content; in Quarto just under the title block, which is
   *  the content's first child. (Jupyter Book pages may start with paragraphs before the heading: still the top.) */
  private mount(root: HTMLElement) {
    if (this.el && this.el.isConnected) return
    this.el = document.createElement('div')
    this.el.className = 'yrS4-legend'
    this.el.setAttribute('data-yrs4', '')
    this.el.setAttribute('role', 'note')
    this.el.setAttribute('aria-label', 'Legend of the marks on this page')
    const after = root.querySelector<HTMLElement>(':scope > #title-block-header, :scope > header.quarto-title-block, :scope > .quarto-title-block')
    if (after) after.insertAdjacentElement('afterend', this.el)
    else root.insertAdjacentElement('afterbegin', this.el)
  }

  render(items: LegendItem[], root: HTMLElement) {
    if (!items.length) {
      this.el?.remove()
      this.el = null
      return
    }
    this.mount(root)
    const el = this.el!
    el.replaceChildren()
    el.classList.toggle('collapsed', this.collapsed)
    if (this.collapsed) {
      const b = document.createElement('button')
      b.type = 'button'
      b.className = 'yrS4-legend-toggle'
      b.textContent = `▸ legend: ${items.length} kind${items.length === 1 ? '' : 's'} of marks on this page (click to see)`
      b.addEventListener('click', () => this.toggle(items, root))
      el.appendChild(b)
      return
    }
    const t = document.createElement('span')
    t.className = 'yrS4-legend-title'
    t.textContent = 'Marks on this page:'
    el.appendChild(t)
    for (const it of items) {
      const s = document.createElement('span')
      s.className = 'yrS4-legend-item'
      s.innerHTML = `<span class="yrS4-legend-line${it.dotted ? ' dotted' : ''}"></span><span class="yrS4-legend-name"></span><span class="yrS4-legend-n"></span>`
      s.style.setProperty('--c', it.color)
      s.querySelector('.yrS4-legend-name')!.textContent = it.name
      s.querySelector('.yrS4-legend-n')!.textContent = `×${it.n}`
      s.title = `${it.n} passage${it.n === 1 ? '' : 's'}; hover to see where`
      s.addEventListener('mouseenter', () => this.onHover(it.id))
      s.addEventListener('mouseleave', () => this.onHover(null))
      el.appendChild(s)
    }
    const b = document.createElement('button')
    b.type = 'button'
    b.className = 'yrS4-legend-toggle'
    b.textContent = '▾ hide legend'
    b.title = 'Collapse the legend on every page of this book'
    b.addEventListener('click', () => this.toggle(items, root))
    el.appendChild(b)
  }

  private toggle(items: LegendItem[], root: HTMLElement) {
    this.collapsed = !this.collapsed
    try {
      localStorage.setItem(KEY, this.collapsed ? '1' : '0')
    } catch { /* ignore */ }
    this.render(items, root)
  }

  remove() {
    this.el?.remove()
    this.el = null
  }
}
