// Fuzzy re-finding (docs/04-anchoring.qmd, step 3): when the exact quote is gone, look for the closest passage.
// Seeds (short exact pieces of the quote) propose candidate positions; a semi-global edit distance scores each
// candidate; the best one is accepted if its distance is at most 20% of the quote's length and the context agrees.
// Written for yrS4; same idea as the approx-string-match library Hypothesis uses, without its bit-parallel code.
import type { Anchor } from '../../../shared/types.ts'

export interface FuzzyHit {
  start: number
  end: number
  distance: number
  score: number          // 1 - distance / quote length
}

const SEED = 6

export function maxErrorsFor(len: number): number {
  if (len < 5) return 0
  return Math.max(2, Math.floor(len * 0.2))
}

/** Candidate start offsets in `text` where `quote` might begin. */
function candidates(quote: string, text: string, limitPerSeed = 60): number[] {
  const seeds: Array<[string, number]> = []
  const n = quote.length
  const positions = n <= SEED ? [0] : [0, Math.floor(n / 2) - Math.floor(SEED / 2), n - SEED]
  for (const p of positions) seeds.push([quote.slice(p, p + SEED), p])
  // long words make good seeds too
  const re = /\S{7,}/g
  let m: RegExpExecArray | null
  while ((m = re.exec(quote)) && seeds.length < 8) seeds.push([m[0].slice(0, 7), m.index])
  const out = new Set<number>()
  for (const [seed, off] of seeds) {
    if (!seed) continue
    let i = text.indexOf(seed)
    let k = 0
    while (i >= 0 && k++ < limitPerSeed) {
      out.add(Math.max(0, i - off))
      i = text.indexOf(seed, i + 1)
    }
  }
  // merge candidates closer than 3 apart
  const sorted = [...out].sort((a, b) => a - b)
  const merged: number[] = []
  for (const c of sorted) if (!merged.length || c - merged[merged.length - 1] > 3) merged.push(c)
  return merged
}

/** Semi-global edit distance: `pattern` against any substring of `text`. Returns the best end position and cost. */
function bestEnd(pattern: string, text: string): { end: number; cost: number } {
  const n = pattern.length, m = text.length
  let prev = new Int32Array(m + 1)   // row for i = 0: free start, all zeros
  let cur = new Int32Array(m + 1)
  for (let i = 1; i <= n; i++) {
    cur[0] = i
    const pc = pattern.charCodeAt(i - 1)
    for (let j = 1; j <= m; j++) {
      const sub = prev[j - 1] + (text.charCodeAt(j - 1) === pc ? 0 : 1)
      const del = prev[j] + 1
      const ins = cur[j - 1] + 1
      cur[j] = sub < del ? (sub < ins ? sub : ins) : del < ins ? del : ins
    }
    const t = prev
    prev = cur
    cur = t
  }
  let end = 0, cost = prev[0]
  for (let j = 1; j <= m; j++) if (prev[j] < cost) {
    cost = prev[j]
    end = j
  }
  return { end, cost }
}

const rev = (s: string) => s.split('').reverse().join('')

export function fuzzyFind(anchor: Anchor, text: string): FuzzyHit | null {
  const q = anchor.quote
  if (!q || !q.exact) return null
  const quote = q.exact
  const n = quote.length
  const maxErr = maxErrorsFor(n)
  if (!maxErr) return null
  let best: FuzzyHit | null = null
  let bestKey = Infinity
  for (const c of candidates(quote, text)) {
    const from = Math.max(0, c - maxErr)
    const to = Math.min(text.length, c + n + maxErr)
    const window = text.slice(from, to)
    const { end, cost } = bestEnd(quote, window)
    if (cost > maxErr) continue
    // find the start by matching the reversed pattern against the reversed window up to `end`
    const back = bestEnd(rev(quote), rev(window.slice(0, end)))
    const start = from + end - back.end
    const absEnd = from + end
    // context agreement: shared characters with the recorded prefix/suffix, as a tie-breaker
    const before = text.slice(Math.max(0, start - q.prefix.length), start)
    const after = text.slice(absEnd, absEnd + q.suffix.length)
    let ctx = 0
    for (let i = 0; i < Math.min(before.length, q.prefix.length); i++) if (before[before.length - 1 - i] === q.prefix[q.prefix.length - 1 - i]) ctx++; else break
    for (let i = 0; i < Math.min(after.length, q.suffix.length); i++) if (after[i] === q.suffix[i]) ctx++; else break
    const posPenalty = anchor.position ? Math.min(5, Math.abs(start - anchor.position.start) / 2000) : 0
    const key = cost * 10 - ctx + posPenalty
    if (key < bestKey) {
      bestKey = key
      best = { start, end: absEnd, distance: cost, score: 1 - cost / n }
    }
  }
  // A short quote with no context agreement is too risky.
  if (best && n < 20 && best.distance > 0) {
    const before = text.slice(Math.max(0, best.start - q.prefix.length), best.start)
    const after = text.slice(best.end, best.end + q.suffix.length)
    const okBefore = q.prefix.length === 0 || before.endsWith(q.prefix.slice(-8))
    const okAfter = q.suffix.length === 0 || after.startsWith(q.suffix.slice(0, 8))
    if (!okBefore && !okAfter) return null
  }
  return best
}
