// The page's "text" (docs/04-anchoring.qmd): the text of the content root, minus ignored elements, with
// whitespace collapsed, plus the maps needed to go from an offset in that text back to a DOM position.

export interface TextChunk {
  node: Text
  rawStart: number       // offset of this node's first character in the raw (uncollapsed) text
}

export interface PageText {
  /** Whitespace-collapsed text: what quotes, prefixes and suffixes are taken from. */
  text: string
  /** normToRaw[i] = index in the raw text of normalized character i (length = text.length + 1). */
  normToRaw: Int32Array
  chunks: TextChunk[]
  root: HTMLElement
  /** Is this text node part of the page text (not ignored)? */
  included: Set<Text>
}

const WS = /\s/

function isIgnored(el: Element | null, ignore: string): boolean {
  if (!el) return false
  try {
    return !!el.closest(ignore)
  } catch {
    return false
  }
}

/** Build the page text of `root`, leaving out anything matching `ignoreSelectors`. */
export function extractText(root: HTMLElement, ignoreSelectors: string[]): PageText {
  const ignore = ignoreSelectors.join(', ')
  const chunks: TextChunk[] = []
  const included = new Set<Text>()
  const raw: string[] = []
  let rawLen = 0
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(n) {
      const p = (n as Text).parentElement
      if (!p || isIgnored(p, ignore)) return NodeFilter.FILTER_REJECT
      return NodeFilter.FILTER_ACCEPT
    },
  })
  let n: Node | null
  while ((n = walker.nextNode())) {
    const t = n as Text
    const s = t.data
    if (!s) continue
    chunks.push({ node: t, rawStart: rawLen })
    included.add(t)
    raw.push(s)
    rawLen += s.length
  }
  const rawText = raw.join('')
  // Collapse whitespace, keeping a map from normalized index to raw index.
  const norm: string[] = []
  const map = new Int32Array(rawText.length + 2)
  let inWs = true // leading whitespace is dropped
  let k = 0
  for (let i = 0; i < rawText.length; i++) {
    const ch = rawText[i]
    if (WS.test(ch) || ch === ' ') {
      if (!inWs) {
        norm.push(' ')
        map[k++] = i
        inWs = true
      }
    } else {
      norm.push(ch)
      map[k++] = i
      inWs = false
    }
  }
  if (norm.length && norm[norm.length - 1] === ' ') {
    norm.pop()
    k--
  }
  map[k] = rawText.length
  return { text: norm.join(''), normToRaw: map.slice(0, k + 1), chunks, root, included }
}

/** Raw offset -> (text node, offset in node). Picks the chunk that contains rawOffset (or the last one). */
export function rawToDom(pt: PageText, rawOffset: number, preferEnd = false): { node: Text; offset: number } {
  const { chunks } = pt
  if (!chunks.length) return { node: document.createTextNode(''), offset: 0 }
  let lo = 0, hi = chunks.length - 1
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1
    if (chunks[mid].rawStart <= rawOffset) lo = mid
    else hi = mid - 1
  }
  let c = chunks[lo]
  // An offset at the very start of a chunk, as an end position, belongs to the previous chunk's end.
  if (preferEnd && lo > 0 && rawOffset === c.rawStart) {
    c = chunks[lo - 1]
  }
  return { node: c.node, offset: Math.min(rawOffset - c.rawStart, c.node.data.length) }
}

/** (text node, offset) -> raw offset. Nodes outside the page text map to the nearest included node. */
export function domToRaw(pt: PageText, node: Node, offset: number): number {
  let target: Node | null = node
  let off = offset
  if (node.nodeType !== Node.TEXT_NODE) {
    // An element boundary: use the first text node at or after that child position.
    const child = node.childNodes[offset] || null
    if (child) {
      const t = firstText(child, pt)
      if (t) return rawStartOf(pt, t)
      // nothing after: the end of the last text before it
      const prev = lastTextBefore(node, offset, pt)
      return prev ? rawStartOf(pt, prev) + prev.data.length : 0
    }
    const prev = lastTextBefore(node, offset, pt)
    if (prev) return rawStartOf(pt, prev) + prev.data.length
    const t = firstText(node, pt)
    return t ? rawStartOf(pt, t) : 0
  }
  if (!pt.included.has(target as Text)) {
    // A text node that is ignored (e.g. a section number): snap to the next included node.
    const walker = document.createTreeWalker(pt.root, NodeFilter.SHOW_TEXT)
    walker.currentNode = target!
    let nx: Node | null
    while ((nx = walker.nextNode())) if (pt.included.has(nx as Text)) return rawStartOf(pt, nx as Text)
    return rawTotal(pt)
  }
  return rawStartOf(pt, target as Text) + off
}

function rawStartOf(pt: PageText, t: Text): number {
  // binary search by node identity is impossible; use a map built lazily
  const m = chunkIndex(pt)
  return m.get(t) ?? 0
}
const indexCache = new WeakMap<PageText, Map<Text, number>>()
function chunkIndex(pt: PageText): Map<Text, number> {
  let m = indexCache.get(pt)
  if (!m) {
    m = new Map()
    for (const c of pt.chunks) m.set(c.node, c.rawStart)
    indexCache.set(pt, m)
  }
  return m
}
function rawTotal(pt: PageText): number {
  const last = pt.chunks[pt.chunks.length - 1]
  return last ? last.rawStart + last.node.data.length : 0
}
function firstText(node: Node, pt: PageText): Text | null {
  if (node.nodeType === Node.TEXT_NODE) return pt.included.has(node as Text) ? (node as Text) : nextIncluded(node, pt)
  const w = document.createTreeWalker(node, NodeFilter.SHOW_TEXT)
  let n: Node | null
  while ((n = w.nextNode())) if (pt.included.has(n as Text)) return n as Text
  return nextIncluded(node, pt)
}
function nextIncluded(node: Node, pt: PageText): Text | null {
  const w = document.createTreeWalker(pt.root, NodeFilter.SHOW_TEXT)
  w.currentNode = node
  let n: Node | null
  while ((n = w.nextNode())) if (pt.included.has(n as Text)) return n as Text
  return null
}
function lastTextBefore(node: Node, offset: number, pt: PageText): Text | null {
  const w = document.createTreeWalker(pt.root, NodeFilter.SHOW_TEXT)
  const child = node.childNodes[offset] || null
  if (child) {
    w.currentNode = child
    let n: Node | null
    while ((n = w.previousNode())) if (pt.included.has(n as Text)) return n as Text
    return null
  }
  // end of node: last included text inside node, else before node
  const inner = document.createTreeWalker(node, NodeFilter.SHOW_TEXT)
  let last: Text | null = null
  let n: Node | null
  while ((n = inner.nextNode())) if (pt.included.has(n as Text)) last = n as Text
  if (last) return last
  w.currentNode = node
  while ((n = w.previousNode())) if (pt.included.has(n as Text)) return n as Text
  return null
}

/** Normalized offset -> raw offset (end offsets map to the raw position just after the last character). */
export function normToRawOffset(pt: PageText, normOffset: number, isEnd = false): number {
  if (normOffset <= 0) return pt.normToRaw[0] ?? 0
  if (normOffset >= pt.text.length) {
    if (isEnd && pt.text.length) return pt.normToRaw[pt.text.length - 1] + 1
    return pt.normToRaw[pt.text.length] ?? rawTotal(pt)
  }
  if (isEnd) return pt.normToRaw[normOffset - 1] + 1
  return pt.normToRaw[normOffset]
}

/** Raw offset -> normalized offset (the first normalized char at or after it). */
export function rawToNormOffset(pt: PageText, rawOffset: number): number {
  const m = pt.normToRaw
  let lo = 0, hi = pt.text.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (m[mid] < rawOffset) lo = mid + 1
    else hi = mid
  }
  return lo
}

/** A DOM Range covering normalized [start, end). */
export function rangeFor(pt: PageText, start: number, end: number): Range | null {
  if (end <= start) return null
  const rs = normToRawOffset(pt, start)
  const re = normToRawOffset(pt, end, true)
  const a = rawToDom(pt, rs)
  const b = rawToDom(pt, re, true)
  const r = document.createRange()
  try {
    r.setStart(a.node, a.offset)
    r.setEnd(b.node, b.offset)
  } catch {
    return null
  }
  return r
}
