// The postMessage channel to the frame, with the frame's origin pinned (docs/03-architecture.qmd).
import { isFrameToPage, type FrameToPage, type PageToFrame } from '../../shared/protocol.ts'

export class Bridge {
  private handlers: Array<(m: FrameToPage) => void> = []
  private queue: PageToFrame[] = []
  private ready = false
  constructor(private iframe: HTMLIFrameElement, readonly origin: string) {
    window.addEventListener('message', (e) => {
      if (e.origin !== this.origin || e.source !== this.iframe.contentWindow) return
      if (!isFrameToPage(e.data)) return
      for (const h of this.handlers) {
        try {
          h(e.data)
        } catch (err) {
          console.error('[yrS4] handler failed', err)
        }
      }
    })
  }
  on(h: (m: FrameToPage) => void) {
    this.handlers.push(h)
  }
  /** The frame is loaded; flush anything queued. */
  markReady() {
    this.ready = true
    const q = this.queue
    this.queue = []
    for (const m of q) this.send(m)
  }
  send(m: PageToFrame) {
    if (!this.ready || !this.iframe.contentWindow) {
      this.queue.push(m)
      return
    }
    this.iframe.contentWindow.postMessage(m, this.origin)
  }
}
