// The in-place editor (D40, his rule of 10-27 evening): a box where the block is, with two tabs, Rendered and
// Markdown. Rendering goes through the frame (it holds the Markdown renderer and the sanitizer); saving sends
// the Markdown to the frame, which stores the proposal. Lives in the page's DOM, marked data-yrs4.

const STYLE_ID = 'yrS4-editor-style'
const CSS = `
.yrS4-editbox { font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; color: #1f2937; border: 1px solid #99f6e4; border-left: 4px solid #0d9488; border-radius: 8px; background: #f0fdfa; margin: 6px 0 14px; box-shadow: 0 4px 16px rgba(13,148,136,.15); }
.yrS4-editbox-tabs { display: flex; align-items: center; gap: 2px; padding: 6px 8px 0; border-bottom: 1px solid #99f6e4; }
.yrS4-editbox-tabs button { border: 1px solid transparent; border-bottom: 0; background: transparent; padding: 4px 10px; border-radius: 6px 6px 0 0; cursor: pointer; font: inherit; font-size: 13px; color: #374151; }
.yrS4-editbox-tabs button.on { background: #fff; border-color: #99f6e4; color: #0f766e; font-weight: 600; }
.yrS4-editbox-tabs .yrS4-editbox-title { margin-left: auto; font-size: 12px; color: #0f766e; }
.yrS4-editbox textarea { display: block; width: 100%; min-height: 120px; box-sizing: border-box; border: 0; background: #fff; padding: 10px 12px; font: 13px/1.5 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; color: #111827; resize: vertical; outline: none; }
.yrS4-editbox-preview { background: #fff; padding: 10px 12px; min-height: 60px; }
.yrS4-editbox-preview > :first-child { margin-top: 0; } .yrS4-editbox-preview > :last-child { margin-bottom: 0; }
.yrS4-editbox-acts { display: flex; align-items: center; gap: 8px; padding: 8px; border-top: 1px solid #99f6e4; flex-wrap: wrap; }
.yrS4-editbox-acts button { font: inherit; font-size: 13px; padding: 5px 12px; border-radius: 6px; border: 1px solid #d1d5db; background: #fff; cursor: pointer; color: #1f2937; }
.yrS4-editbox-acts button.primary { background: #0d9488; color: #fff; border-color: #0d9488; }
.yrS4-editbox-acts button:disabled { opacity: .5; cursor: default; }
.yrS4-editbox-hint { font-size: 11px; color: #6b7280; margin-left: auto; }
.yrS4-editbox-confirm { font-size: 13px; color: #b91c1c; display: inline-flex; align-items: center; gap: 4px; }
.yrS4-editbox-confirm button { font-size: 12px; padding: 3px 8px; }
@media (prefers-color-scheme: dark) { .yrS4-editbox { background: #134e4a; color: #e5e7eb; border-color: #115e59; } .yrS4-editbox textarea, .yrS4-editbox-preview { background: #111827; color: #e5e7eb; } .yrS4-editbox-tabs button { color: #d1d5db; } .yrS4-editbox-tabs button.on { background: #111827; color: #5eead4; } .yrS4-editbox-acts button { background: #1f2937; color: #e5e7eb; border-color: #4b5563; } }
@media print { .yrS4-editbox { display: none; } }
`

export interface EditorOptions {
  title: string                         // "Paragraph" / "List"
  markdown: string
  render(md: string): Promise<string>   // sanitized HTML, from the frame
  onSave(md: string): void
  onCancel(): void
  /** Called every few seconds while the text differs from what was last saved (a draft in the database). */
  onDraft?(md: string): void
  draftNote?: string                    // shown when the editor opened from a saved draft
}

export class InlineEditor {
  private box: HTMLElement | null = null
  private target: HTMLElement | null = null
  private prevDisplay = ''

  get isOpen() {
    return !!this.box
  }
  get element() {
    return this.target
  }

  open(el: HTMLElement, o: EditorOptions) {
    this.close(false)
    if (!document.getElementById(STYLE_ID)) {
      const st = document.createElement('style')
      st.id = STYLE_ID
      st.setAttribute('data-yrs4', '')
      st.textContent = CSS
      document.head.appendChild(st)
    }
    this.target = el
    this.prevDisplay = el.style.display
    const box = document.createElement('div')
    box.className = 'yrS4-editbox'
    box.setAttribute('data-yrs4', '')
    box.setAttribute('role', 'dialog')
    box.setAttribute('aria-label', 'Edit this text')
    const tabs = document.createElement('div')
    tabs.className = 'yrS4-editbox-tabs'
    const tMd = document.createElement('button')
    tMd.type = 'button'
    tMd.textContent = 'Markdown'
    const tRe = document.createElement('button')
    tRe.type = 'button'
    tRe.textContent = 'Rendered'
    const title = document.createElement('span')
    title.className = 'yrS4-editbox-title'
    title.textContent = `${o.title} · your edit, shown to you only`
    tabs.append(tMd, tRe, title)
    const ta = document.createElement('textarea')
    ta.value = o.markdown
    ta.spellcheck = true
    const preview = document.createElement('div')
    preview.className = 'yrS4-editbox-preview'
    preview.hidden = true
    const acts = document.createElement('div')
    acts.className = 'yrS4-editbox-acts'
    const save = document.createElement('button')
    save.type = 'button'
    save.className = 'primary'
    save.textContent = 'Save'
    const cancel = document.createElement('button')
    cancel.type = 'button'
    cancel.textContent = 'Cancel'
    const reset = document.createElement('button')
    reset.type = 'button'
    reset.textContent = 'Reset'
    reset.title = 'Back to the text as it was when you opened the editor'
    const hint = document.createElement('span')
    hint.className = 'yrS4-editbox-hint'
    hint.textContent = 'Ctrl+Enter saves · Esc cancels · the book\'s source is unchanged until the proposal is applied'
    const status = document.createElement('span')
    status.className = 'yrS4-editbox-hint'
    status.textContent = o.draftNote || ''
    acts.append(save, cancel, reset, status, hint)
    box.append(tabs, ta, preview, acts)
    // autosave: every 4 s, if the text changed since the last draft or save
    let lastDraft = o.markdown
    let dirty = false
    ta.addEventListener('input', () => { dirty = true })
    const timer = o.onDraft ? window.setInterval(() => {
      if (!dirty || ta.value === lastDraft) return
      lastDraft = ta.value
      dirty = false
      o.onDraft!(ta.value)
      status.textContent = `draft saved ${new Date().toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit', second: '2-digit' })}`
    }, 4000) : 0
    this.cleanup = () => { if (timer) clearInterval(timer) }
    const changed = () => ta.value !== o.markdown

    const fit = () => {
      ta.style.height = 'auto'
      ta.style.height = `${Math.max(120, ta.scrollHeight + 4)}px`
    }
    ta.addEventListener('input', fit)
    const showMd = () => {
      tMd.classList.add('on')
      tRe.classList.remove('on')
      preview.hidden = true
      ta.hidden = false
      ta.focus({ preventScroll: true })
    }
    const showRendered = async () => {
      tRe.classList.add('on')
      tMd.classList.remove('on')
      preview.innerHTML = '<span style="color:#6b7280">rendering…</span>'
      preview.hidden = false
      ta.hidden = true
      try {
        preview.innerHTML = await o.render(ta.value)
      } catch {
        preview.textContent = 'Could not render the preview.'
      }
    }
    tMd.addEventListener('click', showMd)
    tRe.addEventListener('click', showRendered)
    save.addEventListener('click', () => {
      if (!ta.value.trim()) return
      const md = ta.value
      this.close(false)
      o.onSave(md)
    })
    cancel.addEventListener('click', () => {
      if (!changed() && lastDraft === o.markdown) {
        this.close(false)
        o.onCancel()
        return
      }
      // an in-box question, not a browser dialog: "Discard your changes?"
      if (acts.querySelector('.yrS4-editbox-confirm')) return
      const q = document.createElement('span')
      q.className = 'yrS4-editbox-confirm'
      q.append('Discard your changes? ')
      const yes = document.createElement('button')
      yes.type = 'button'
      yes.textContent = 'Discard'
      yes.style.color = '#b91c1c'
      const no = document.createElement('button')
      no.type = 'button'
      no.textContent = 'Keep editing'
      q.append(yes, ' ', no)
      yes.addEventListener('click', () => {
        this.close(false)
        o.onCancel()
      })
      no.addEventListener('click', () => {
        q.remove()
        ta.focus({ preventScroll: true })
      })
      acts.insertBefore(q, reset)
      no.focus()
    })
    reset.addEventListener('click', () => {
      ta.value = o.markdown
      fit()
      if (!preview.hidden) void showRendered()
    })
    box.addEventListener('keydown', (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
        e.preventDefault()
        save.click()
      } else if (e.key === 'Escape') {
        e.preventDefault()
        cancel.click()
      }
      e.stopPropagation()
    })
    el.insertAdjacentElement('afterend', box)
    el.style.display = 'none'
    this.box = box
    showMd()
    fit()
    box.scrollIntoView({ block: 'nearest' })
  }

  private cleanup: (() => void) | null = null
  close(fire = true) {
    if (!this.box) return
    this.cleanup?.()
    this.cleanup = null
    this.box.remove()
    this.box = null
    if (this.target) this.target.style.display = this.prevDisplay
    this.target = null
    void fire
  }
}
