// The label table of contents (docs/06a-labels.qmd, D39): a full page, inside the book, listing every place
// in the whole book that carries each label, with links. One link per page by default; a switch lists every
// labeled section. Opened from the book's sidebar ("Table of contents by label") or the panel's Labels tab.
import type { LabelInfo } from '../../../shared/types.ts'
import type { TocEntry } from '../../../shared/protocol.ts'

const MODE_KEY = 'yrS4-toc-mode'
const STYLE_ID = 'yrS4-toc-style'
export type TocMode = 'page' | 'section'

/** The list's styles: used in the shadow root (the full-page view) and in the book's own page (inline). */
export const TOC_CSS = `
.yrS4-toc-in { max-width: 860px; margin: 0 auto; padding: 24px 28px 60px; }
.yrS4-toc-inline .yrS4-toc-in { max-width: none; padding: 0; }
.yrS4-toc-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; border-bottom: 1px solid #e5e7eb; padding-bottom: 10px; margin-bottom: 12px; }
.yrS4-toc-head h1 { font-size: 22px; margin: 0; flex: 1; }
.yrS4-toc-inline .yrS4-toc-head { border: 0; padding: 0; }
.yrS4-toc-mode { display: flex; gap: 10px; font-size: 13px; color: #374151; }
.yrS4-toc-mode label { display: inline-flex; gap: 4px; align-items: center; cursor: pointer; font-weight: normal; }
.yrS4-toc-jump { display: flex; flex-wrap: wrap; gap: 6px; margin: 10px 0 18px; }
.yrS4-toc-jump a { text-decoration: none; }
.yrS4-toc-jump .yrS4-chip { display: inline-flex; align-items: center; gap: 5px; border: 1px solid #d1d5db; background: #fff; color: #1f2937; border-radius: 999px; padding: 2px 9px 2px 6px; font-size: 12px; cursor: pointer; }
.yrS4-toc-jump .yrS4-chip-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--c); }
.yrS4-toc-in h2 { font-size: 18px; margin: 22px 0 6px; display: flex; align-items: center; gap: 8px; border: 0; }
.yrS4-toc-in h2 .yrS4-legend-line { width: 4px; height: 20px; border-radius: 2px; display: inline-block; }
.yrS4-toc-in ol { margin: 0; padding-left: 26px; }
.yrS4-toc-in li { margin: 3px 0; }
.yrS4-toc-page > summary { cursor: pointer; list-style: none; }
.yrS4-toc-page > summary::before { content: "▸"; display: inline-block; width: 1em; color: #6b7280; }
.yrS4-toc-page[open] > summary::before { content: "▾"; }
.yrS4-toc-page > ul { margin: 2px 0 6px; padding-left: 2em; list-style: none; }
.yrS4-toc-page > ul li::before { content: "– "; color: #9ca3af; }
@media print { .yrS4-toc-page > summary::before { content: ""; } }
.yrS4-toc-n { color: #6b7280; font-size: 13px; }
.yrS4-toc-sub { color: #6b7280; font-size: 13px; margin: 0 0 8px; }
.yrS4-toc-close { border: 1px solid #d1d5db; background: #fff; border-radius: 6px; padding: 5px 10px; cursor: pointer; font: inherit; font-size: 13px; color: #1f2937; }
@media (prefers-color-scheme: dark) { .yrS4-toc-close { background: #1f2937; color: #e5e7eb; border-color: #4b5563; } .yrS4-toc-jump .yrS4-chip { background: #1f2937; color: #e5e7eb; } }
@media print { .yrS4-toc-close, .yrS4-toc-mode { display: none; } }
`

export interface TocData { base: string; labels: LabelInfo[]; entries: TocEntry[] }

export class TocView {
  el: HTMLElement
  private data: TocData | null = null
  private mode: TocMode
  private inline: HTMLElement | null = null     // the book's own "Table of contents by label" page, when it has one
  constructor(shadow: ShadowRoot) {
    this.el = document.createElement('div')
    this.el.className = 'yrS4-tocview'
    this.el.setAttribute('role', 'dialog')
    this.el.setAttribute('aria-label', 'Table of contents by label')
    this.el.hidden = true
    shadow.appendChild(this.el)
    let m: string | null = null
    try {
      m = localStorage.getItem(MODE_KEY)
    } catch { /* ignore */ }
    this.mode = m === 'section' ? 'section' : 'page'
    document.addEventListener('keydown', (e) => {
      if (!this.el.hidden && e.key === 'Escape') this.hide()
    })
    // The full-page view is a history entry, so Back closes it and Back from a page it linked to returns to it.
    window.addEventListener('popstate', () => {
      if (!this.el.hidden && !location.hash.includes('yrS4-toc')) this.hide(false)
    })
  }

  /** The book has its own page for the list (a container with data-yrs4-toc): render there, as part of the page. */
  mountInline(container: HTMLElement) {
    this.inline = container
    if (!document.getElementById(STYLE_ID)) {
      const st = document.createElement('style')
      st.id = STYLE_ID
      st.setAttribute('data-yrs4', '')
      st.textContent = TOC_CSS
      document.head.appendChild(st)
    }
    container.classList.add('yrS4-toc-inline')
    container.setAttribute('data-yrs4', '')          // the overlay ignores its own list: no boxes, no text anchoring
  }
  get isInline() {
    return !!this.inline
  }
  /** The page exists but nothing is labeled yet: say what it is for instead of an empty list. */
  showEmpty() {
    if (!this.inline) return
    this.inline.replaceChildren()
    const p = document.createElement('p')
    p.className = 'yrS4-toc-sub'
    p.textContent = 'Nothing in this book carries a label yet. When your instructor labels passages ("Covered in class", "Read before the midterm") and publishes the label to your section, or when you label passages yourself, this page lists every labeled place in the book, under its label, with links. Until then the page stays out of the book\'s menu.'
    this.inline.appendChild(p)
  }

  get visible() {
    return !this.el.hidden
  }

  show(data: TocData) {
    this.data = data
    if (this.inline) {
      this.render(this.inline)
      return
    }
    this.render(this.el)
    if (this.el.hidden) {
      this.el.hidden = false
      if (!location.hash.includes('yrS4-toc')) history.pushState({ yrS4toc: 1 }, '', '#yrS4-toc')
    }
    this.el.scrollTop = 0
    this.el.querySelector<HTMLElement>('button')?.focus({ preventScroll: true })
  }
  hide(back = true) {
    if (this.inline || this.el.hidden) return
    this.el.hidden = true
    if (back && location.hash.includes('yrS4-toc')) history.back()
  }

  private setMode(m: TocMode) {
    this.mode = m
    try {
      localStorage.setItem(MODE_KEY, m)
    } catch { /* ignore */ }
    this.render(this.inline || this.el)
  }

  private render(el: HTMLElement) {
    const d = this.data
    if (!d) return
    el.replaceChildren()
    const inner = document.createElement('div')
    inner.className = 'yrS4-toc-in'
    el.appendChild(inner)
    const head = document.createElement('div')
    head.className = 'yrS4-toc-head'
    if (!this.inline) {
      const h1 = document.createElement('h1')
      h1.textContent = 'Table of contents by label'
      head.appendChild(h1)
    }
    const mode = document.createElement('div')
    mode.className = 'yrS4-toc-mode'
    for (const [open, text] of [[true, 'Expand all'], [false, 'Collapse all']] as Array<[boolean, string]>) {
      const b = document.createElement('button')
      b.type = 'button'
      b.className = 'yrS4-toc-close'
      b.textContent = text
      b.addEventListener('click', () => {
        this.mode = open ? 'section' : 'page'
        try { localStorage.setItem(MODE_KEY, this.mode) } catch { /* ignore */ }
        el.querySelectorAll<HTMLDetailsElement>('details.yrS4-toc-page').forEach((d) => { d.open = open })
      })
      mode.appendChild(b)
    }
    head.appendChild(mode)
    const print = document.createElement('button')
    print.type = 'button'
    print.className = 'yrS4-toc-close'
    print.textContent = 'Print'
    print.addEventListener('click', () => window.print())
    head.appendChild(print)
    if (!this.inline) {
      const close = document.createElement('button')
      close.type = 'button'
      close.className = 'yrS4-toc-close'
      close.textContent = '✕ Close'
      close.addEventListener('click', () => this.hide())
      head.appendChild(close)
    }
    inner.appendChild(head)

    const labels = d.labels.filter((l) => d.entries.some((e) => e.label === l.id))
    if (!labels.length) {
      const p = document.createElement('p')
      p.className = 'yrS4-toc-sub'
      p.textContent = 'Nothing in this book carries a label you can see yet. Labels your instructor publishes to your section, and labels you apply yourself, are listed here under their names, with links to every place in the book that carries them.'
      inner.appendChild(p)
      return
    }
    const sub = document.createElement('p')
    sub.className = 'yrS4-toc-sub'
    sub.textContent = 'Each page that carries the label, in book order. Open a page (▸) for the places on it.'
    inner.appendChild(sub)
    const jump = document.createElement('div')
    jump.className = 'yrS4-toc-jump'
    for (const l of labels) {
      const a = document.createElement('a')
      a.href = `#yrS4-toc-${l.id}`
      a.className = 'yrS4-chip'
      a.style.setProperty('--c', l.color)
      a.innerHTML = '<span class="yrS4-chip-dot"></span><span class="yrS4-chip-name"></span>'
      a.querySelector('.yrS4-chip-name')!.textContent = l.name
      a.addEventListener('click', (e) => {
        e.preventDefault()
        el.querySelector<HTMLElement>(`[data-label="${l.id}"]`)?.scrollIntoView({ behavior: 'smooth', block: 'start' })
      })
      jump.appendChild(a)
    }
    inner.appendChild(jump)

    for (const l of labels) {
      const h2 = document.createElement('h2')
      h2.setAttribute('data-label', l.id)
      h2.innerHTML = '<span class="yrS4-legend-line"></span><span></span>'
      ;(h2.firstElementChild as HTMLElement).style.setProperty('--c', l.color)
      ;(h2.firstElementChild as HTMLElement).style.background = l.color
      h2.lastElementChild!.textContent = l.name
      inner.appendChild(h2)
      const ol = document.createElement('ol')
      const mine = d.entries.filter((e) => e.label === l.id).sort((a, b) => a.order - b.order)
      const byPage = new Map<string, TocEntry[]>()
      for (const e of mine) byPage.set(e.page, [...(byPage.get(e.page) || []), e])
      for (const [, es] of byPage) {
        const first = es[0]
        const li = document.createElement('li')
        const whole = es.some((e) => e.scope === 'page')
        // the places on the page, one per section (a page-wide label is one place)
        const seenKey = new Set<string>()
        const places = es.filter((e) => {
          const key = e.scope === 'page' ? '' : e.headingId || ''
          if (seenKey.has(key)) return false
          seenKey.add(key)
          return true
        })
        const pageLink = document.createElement('a')
        pageLink.href = this.link(first, false)
        pageLink.textContent = first.pageTitle
        const note = document.createElement('span')
        note.className = 'yrS4-toc-n'
        const exc = [...new Set(es.flatMap((e) => e.except || []))]
        note.textContent = (whole ? ' · whole page' : places.length > 1 ? ` · ${places.length} places` : places[0].headingText ? ` · ${places[0].number ? places[0].number + ' ' : ''}${places[0].headingText}${places[0].scope === 'text' ? ' (part)' : ''}` : '') + (exc.length ? ` (except ${exc.join(', ')})` : '')
        if (places.length > 1 || (places.length === 1 && !whole && places[0].scope !== 'page')) {
          const det = document.createElement('details')
          det.className = 'yrS4-toc-page'
          det.open = this.mode === 'section'
          const sum = document.createElement('summary')
          sum.append(pageLink, note)
          det.appendChild(sum)
          const inner2 = document.createElement('ul')
          for (const e of places) {
            const li2 = document.createElement('li')
            const a = document.createElement('a')
            a.href = this.link(e, true)
            a.textContent = e.scope === 'page' || !e.headingText ? 'whole page' : `${e.number ? e.number + ' ' : ''}${e.headingText}`
            li2.appendChild(a)
            if (e.scope === 'text') {
              const n = document.createElement('span')
              n.className = 'yrS4-toc-n'
              n.textContent = ' · part of it'
              li2.appendChild(n)
            }
            if (e.except?.length) {
              const x = document.createElement('span')
              x.className = 'yrS4-toc-n'
              x.textContent = ` (except ${e.except.join(', ')})`
              li2.appendChild(x)
            }
            inner2.appendChild(li2)
          }
          det.appendChild(inner2)
          li.appendChild(det)
        } else {
          li.append(pageLink, note)
        }
        ol.appendChild(li)
      }
      inner.appendChild(ol)
    }
  }

  private link(e: TocEntry, withHeading: boolean): string {
    const base = this.data!.base
    const url = base + e.path
    return withHeading && e.headingId ? `${url}#${e.headingId}` : url
  }
}
