// The Quarto adapter: Quarto 1.x books and websites (the instructor's AI book, docs/11-books.qmd).
import { OVERLAY_IGNORE, afterQuiet, type BookAdapter, type Container, type HeadingInfo } from './types.ts'

function textOf(el: Element): string {
  const c = el.cloneNode(true) as Element
  c.querySelectorAll('.header-section-number, .chapter-number, .anchorjs-link, [data-yrs4]').forEach((x) => x.remove())
  return (c.textContent || '').replace(/\s+/g, ' ').trim()
}

export const quarto: BookAdapter = {
  name: 'quarto',
  detect: () => !!document.querySelector('meta[name="generator"][content^="quarto"], main#quarto-document-content'),
  contentRoot: () => (document.querySelector('main#quarto-document-content') as HTMLElement) || (document.querySelector('main') as HTMLElement) || document.body,
  ignore: [
    ...OVERLAY_IGNORE,
    '.chapter-number', '.header-section-number', '.anchorjs-link', '.quarto-section-identifier',
    '#toc-title', 'nav#TOC', '.nav-tabs',                                   // tab labels
    '.yr-collapse-buttons', '.yr-collapse-btn', '.yr-ways-btn', '.yr-ways-title', '.yr-update-bar', // script-generated
    '.callout-toggle', '.code-copy-button', '.code-tools-button', 'button',
  ],
  headings(): HeadingInfo[] {
    const root = this.contentRoot()
    const out: HeadingInfo[] = []
    for (const h of Array.from(root.querySelectorAll<HTMLElement>('h1, h2, h3, h4, h5, h6'))) {
      if (h.closest('#title-block-header, .quarto-title-block, nav, #TOC, .callout-header, [data-yrs4]')) continue
      if (h.id === 'toc-title' || h.classList.contains('title')) continue
      const section = (h.closest('section[id]') as HTMLElement) || h.parentElement || root
      const id = (section && section.querySelector('h1,h2,h3,h4,h5,h6') === h ? section.id : '') || h.id || h.getAttribute('data-anchor-id') || ''
      const text = textOf(h)
      if (!text) continue
      out.push({ id, text, level: Number(h.tagName[1]), element: h, section })
    }
    return out
  },
  containers(): Container[] {
    const root = this.contentRoot()
    const out: Container[] = []
    for (const callout of Array.from(root.querySelectorAll<HTMLElement>('.callout.callout-titled'))) {
      const body = callout.querySelector<HTMLElement>('.callout-collapse')
      const header = callout.querySelector<HTMLElement>('.callout-header')
      if (!body || !header) continue
      out.push({
        element: body,
        header,
        isOpen: () => body.classList.contains('show') || !body.classList.contains('collapse'),
        open: () => {
          if (!body.classList.contains('show')) header.click()
        },
      })
    }
    for (const d of Array.from(root.querySelectorAll<HTMLDetailsElement>('details'))) {
      const summary = d.querySelector<HTMLElement>('summary') || d
      out.push({ element: d, header: summary, isOpen: () => d.open, open: () => { d.open = true } })
    }
    for (const pane of Array.from(root.querySelectorAll<HTMLElement>('.panel-tabset .tab-pane'))) {
      const tabset = pane.closest('.panel-tabset')!
      const link = tabset.querySelector<HTMLElement>(`a.nav-link[href="#${pane.id}"], a.nav-link[data-bs-target="#${pane.id}"]`)
      out.push({
        element: pane,
        header: link || (tabset.querySelector('.nav-tabs') as HTMLElement) || pane,
        isOpen: () => pane.classList.contains('active'),
        open: () => link?.click(),
      })
    }
    return out
  },
  sidebarLinks(): Map<string, HTMLElement> {
    const m = new Map<string, HTMLElement>()
    for (const a of Array.from(document.querySelectorAll<HTMLAnchorElement>('nav#quarto-sidebar a.sidebar-link[href]'))) {
      const href = a.getAttribute('href') || ''
      if (!href || href.startsWith('#')) continue
      try {
        const u = new URL(href, location.href)
        if (u.origin !== location.origin && !u.href.startsWith('https://')) continue
        m.set(u.pathname.replace(/^\//, ''), a)
      } catch { /* ignore */ }
    }
    return m
  },
  settled: () => afterQuiet(() => document.querySelector('main#quarto-document-content') as HTMLElement, 300),
  blockKind(node: Node) {
    const el = node.nodeType === 1 ? (node as Element) : node.parentElement
    if (!el) return 'prose'
    if (el.closest('.cell-output, .cell-output-display, .cell-output-stdout')) return 'output'
    if (el.closest('pre, code, .sourceCode')) return 'code'
    if (el.closest('table')) return 'table'
    if (el.closest('figure, .figure, .quarto-figure')) return 'figure'
    if (el.closest('.callout')) return 'callout'
    return 'prose'
  },
}
