// Find a mark's text again (docs/04-anchoring.qmd, "Finding a mark again"). First release: exact quote only;
// several matches are told apart by prefix/suffix, then by closeness to the recorded position. Otherwise orphan.
import type { Anchor } from '../../../shared/types.ts'
import type { HeadingInfo } from '../adapters/index.ts'
import { rangeFor, type PageText } from './text.ts'

export interface Found {
  range: Range
  start: number
  end: number
  how: 'exact' | 'exact-context' | 'section' | 'page'
  element?: HTMLElement        // for section and page scope
}

function commonSuffixLen(a: string, b: string): number {
  let n = 0
  while (n < a.length && n < b.length && a[a.length - 1 - n] === b[b.length - 1 - n]) n++
  return n
}
function commonPrefixLen(a: string, b: string): number {
  let n = 0
  while (n < a.length && n < b.length && a[n] === b[n]) n++
  return n
}

export function findQuote(anchor: Anchor, pt: PageText): Found | null {
  const q = anchor.quote
  if (!q || !q.exact) return null
  const text = pt.text
  const hits: number[] = []
  let i = text.indexOf(q.exact)
  while (i >= 0 && hits.length < 5000) {
    hits.push(i)
    i = text.indexOf(q.exact, i + 1)
  }
  if (!hits.length) return null
  let best = hits[0]
  let how: Found['how'] = 'exact'
  if (hits.length > 1) {
    how = 'exact-context'
    let bestScore = -1
    for (const h of hits) {
      const before = text.slice(Math.max(0, h - q.prefix.length), h)
      const after = text.slice(h + q.exact.length, h + q.exact.length + q.suffix.length)
      // context first (up to 64 matching characters, ten points each), then closeness to the recorded position
      // (one point per 100 characters), which decides between identical repeats such as a long traceback
      let score = (commonSuffixLen(before, q.prefix) + commonPrefixLen(after, q.suffix)) * 10
      if (anchor.position) score -= Math.abs(h - anchor.position.start) / 100
      if (score > bestScore) {
        bestScore = score
        best = h
      }
    }
  }
  const range = rangeFor(pt, best, best + q.exact.length)
  return range ? { range, start: best, end: best + q.exact.length, how } : null
}

/** Section scope: by heading id, then by heading text. */
export function findSection(anchor: Anchor, headings: HeadingInfo[]): Found | null {
  if (!anchor.section) return null
  const want = anchor.section
  let h = want.id ? headings.find((x) => x.id === want.id) : undefined
  if (!h && want.headings.length) {
    const last = want.headings[want.headings.length - 1].toLowerCase()
    h = headings.find((x) => x.text.toLowerCase() === last)
  }
  if (!h) return null
  const range = document.createRange()
  range.selectNodeContents(h.section)
  return { range, start: 0, end: 0, how: 'section', element: h.section }
}

export function findAnchor(anchor: Anchor, pt: PageText, headings: HeadingInfo[]): Found | null {
  switch (anchor.scope) {
    case 'page': {
      const range = document.createRange()
      range.selectNodeContents(pt.root)
      return { range, start: 0, end: pt.text.length, how: 'page', element: pt.root }
    }
    case 'section':
      return findSection(anchor, headings)
    default:
      return findQuote(anchor, pt)
  }
}
