// The Jupyter Book v1 (Sphinx / pydata theme) adapter: yrThinkPython. Finished in Week 1 (docs/13-roadmap.qmd).
import { OVERLAY_IGNORE, afterQuiet, type BookAdapter, type Container, type HeadingInfo } from './types.ts'

const text = (el: Element) => {
  const c = el.cloneNode(true) as Element
  c.querySelectorAll('.headerlink, .section-number, [data-yrs4]').forEach((x) => x.remove())
  return (c.textContent || '').replace(/\s+/g, ' ').trim()
}

export const jupyterBook: BookAdapter = {
  name: 'jupyter-book',
  detect: () => !!document.querySelector('article.bd-article, meta[name="generator"][content*="sphinx" i]'),
  contentRoot: () => (document.querySelector('article.bd-article') as HTMLElement) || (document.querySelector('main') as HTMLElement) || document.body,
  ignore: [...OVERLAY_IGNORE, '.headerlink', '.prompt', '.section-number', 'button', '.toggle-button', '.yr-collapse-btn'],
  headings(): HeadingInfo[] {
    const root = this.contentRoot()
    const out: HeadingInfo[] = []
    for (const h of Array.from(root.querySelectorAll<HTMLElement>('h1, h2, h3, h4, h5, h6'))) {
      if (h.closest('nav, .bd-toc, [data-yrs4]')) continue
      const section = (h.closest('section[id]') as HTMLElement) || (h.closest('details') as HTMLElement) || h.parentElement || root
      const id = h.id || section.id || ''
      const t = text(h)
      if (!t) continue
      out.push({ id, text: t, level: Number(h.tagName[1]), element: h, section })
    }
    return out
  },
  containers(): Container[] {
    const root = this.contentRoot()
    const out: Container[] = []
    for (const d of Array.from(root.querySelectorAll<HTMLDetailsElement>('details'))) {
      const summary = d.querySelector<HTMLElement>('summary') || d
      out.push({ element: d, header: summary, isOpen: () => d.open, open: () => { d.open = true } })
    }
    for (const dd of Array.from(root.querySelectorAll<HTMLElement>('.dropdown.admonition, .toggle'))) {
      const header = dd.querySelector<HTMLElement>('.admonition-title, .toggle-button') || dd
      out.push({
        element: dd,
        header,
        isOpen: () => !dd.classList.contains('toggle-hidden') && dd.classList.contains('toggle-shown') || dd.classList.contains('open'),
        open: () => { if (!dd.classList.contains('toggle-shown')) header.click() },
      })
    }
    return out
  },
  sidebarLinks(): Map<string, HTMLElement> {
    const m = new Map<string, HTMLElement>()
    for (const a of Array.from(document.querySelectorAll<HTMLAnchorElement>('nav.bd-docs-nav a.reference.internal[href], .bd-sidebar a.reference.internal[href], .bd-sidebar-primary a.reference.internal[href]'))) {
      const href = a.getAttribute('href') || ''
      if (!href || href.startsWith('#')) continue
      try {
        const u = new URL(href, location.href)
        if (u.origin !== location.origin && !u.href.startsWith('https://')) continue
        m.set(u.pathname.replace(/^\//, ''), a)
      } catch { /* ignore */ }
    }
    return m
  },
  settled: () => new Promise((r) => {
    const go = () => afterQuiet(() => document.querySelector('article.bd-article') as HTMLElement, 400).then(r)
    if (document.readyState === 'complete') go()
    else window.addEventListener('load', go, { once: true })
  }),
  blockKind(node: Node) {
    const el = node.nodeType === 1 ? (node as Element) : node.parentElement
    if (!el) return 'prose'
    if (el.closest('.cell_output, .output')) return 'output'
    if (el.closest('pre, code, .highlight, .cell_input')) return 'code'
    if (el.closest('table')) return 'table'
    if (el.closest('figure, .figure')) return 'figure'
    if (el.closest('.admonition')) return 'callout'
    return 'prose'
  },
}
