import type { BookAdapter } from './types.ts'
import { quarto } from './quarto.ts'
import { jupyterBook } from './jupyterbook.ts'
import { plain } from './plain.ts'

export type { BookAdapter, HeadingInfo, Container } from './types.ts'

/** Pick the adapter: the one the package's manifest names, else by detection. */
export function pickAdapter(generator?: string | null): BookAdapter {
  const byName: Record<string, BookAdapter> = { quarto, 'jupyter-book': jupyterBook, other: plain }
  if (generator && byName[generator] && byName[generator].detect()) return byName[generator]
  for (const a of [quarto, jupyterBook]) if (a.detect()) return a
  return plain
}
