// What the page script asks a book adapter (docs/11-books.qmd, "Adapters").

export interface HeadingInfo {
  id: string
  text: string
  level: number
  element: HTMLElement
  /** The element that holds this heading's section (heading to the next heading of the same level). */
  section: HTMLElement
}

export interface Container {
  element: HTMLElement          // the element whose content can be hidden
  isOpen(): boolean
  open(): void
  /** Where to show the "there is a mark inside" badge when closed. */
  header: HTMLElement
}

export interface BookAdapter {
  name: 'quarto' | 'jupyter-book' | 'other'
  detect(): boolean
  contentRoot(): HTMLElement
  /** Selectors whose text is never part of the anchoring text (generated numbers, buttons, the overlay). */
  ignore: string[]
  headings(): HeadingInfo[]
  containers(): Container[]
  sidebarLinks(): Map<string, HTMLElement>
  settled(): Promise<void>
  /** Classify the block a node sits in. */
  blockKind(node: Node): 'prose' | 'code' | 'output' | 'callout' | 'table' | 'figure'
}

export const OVERLAY_IGNORE = ['[data-yrs4]', '.yrS4-host', 'script', 'style', 'noscript', 'template']

export function quiet(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms))
}

/** Resolves after DOMContentLoaded (or at once), then after `ms` of no DOM mutations under root (max 2 s). */
export function afterQuiet(root: () => HTMLElement | null, ms = 250): Promise<void> {
  return new Promise((resolve) => {
    const start = () => {
      const el = root()
      if (!el) return resolve()
      let timer = setTimeout(done, ms)
      const limit = setTimeout(done, 2000)
      const mo = new MutationObserver(() => {
        clearTimeout(timer)
        timer = setTimeout(done, ms)
      })
      mo.observe(el, { childList: true, subtree: true, characterData: true })
      function done() {
        clearTimeout(timer)
        clearTimeout(limit)
        mo.disconnect()
        resolve()
      }
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true })
    else start()
  })
}
